(window.EX_CHUNKS=window.EX_CHUNKS||{})["b46"]={"讨价还价":[["在菜市场，顾客和摊主为了几毛钱讨价还价。","كۆكتات بازىرىدا، خېرىدارلار بىلەن ساتقۇچىلار بىر نەچچە مو چاڭگە ئۈچۈن باھا تالىشىدۇ.","köktat bazirida, xéridarlar bilen satquchilar bir nechche mo changge üchün baha talishidu."]],"隔阂":[["他们之间因文化差异而产生隔阂。","ئۇلارنىڭ ئارىسىدا مەدەنىيەت پەرقى سەۋەبىدىن ئارىلىق پەيدا بولدى.","ularning arisida medeniyet perqi sewebidin ariliq peyda boldi."]],"迄今为止":[["迄今为止，项目进展顺利。","شۇ ۋاقىتقىچە، تۈر ئوڭۇشلۇق ئېلىپ بېرىلدى.","shu waqitqiche, tür ongushluq élip bérildi."]],"朝气蓬勃":[["青年们朝气蓬勃，充满活力。","ياشلار غەيرەت-شەۋقەت بىلەن تولۇپ، ھاياتىي كۈچكە ئىگە.","yashlar gheyret-shewqet bilen tolup, hayatiy küchke ige."]],"作弊":[["考试时作弊会被取消资格。","ئىمتىھاندا كۆچۈرۈمچىلىك قىلغانلارنىڭ سالاھىيىتى بىكار قىلىنىدۇ.","imtihanda köchürümchilik qilghanlarning salahiyiti bikar qilinidu."]],"劮":[["这个字读作“劮”，常用于古文中。","بۇ خەت «يى» دەپ ئوقۇلىدۇ، كۆپىنچە قەدىمكى ئەسەرلەردە ئىشلىتىلىدۇ.","bu xet «yi» dep oqulidu, köpinche qedimki eserlerde ishlitilidu."]],"懮":[["他感到懮郁。","ئۇ غەمكىن ھېس قىلدى.","u ghemkin hés qildi."]],"摮":[["他摮起袖子，露出结实的手臂。","ئۇ يېڭىنى تۈرۈپ، مۇستەھكەم بىلىكىنى كۆرسەتتى.","u yéngini türüp, mustehkem bilikini körsetti."]],"斮":[["工匠用斧头斮下木头。","ھۈنەرۋەن پالتا بىلەن ياغاچنى چاپتى.","hünerwen palta bilen yaghachni chapti."]],"柮":[["这种柮树适合做木材。","بۇ خىل دەرەخ ياغاچ ماتېرىيالى قىلىشقا ماس كېلىدۇ.","bu xil derex yaghach matériyali qilishqa mas kélidu."]],"椮":[["这种椮木十分稀有珍贵。","بۇ خىل ئارچا ياغىچى ئىنتايىن ئاز ئۇچرايدىغان ۋە قىممەتلىك.","bu xil archa yaghichi intayin az uchraydighan we qimmetlik."]],"渮":[["这潭水颜色深渮，令人感到神秘。","بۇ كۆلچەكنىڭ سۈيى تېرىق رەڭدە، سىرلىق تۇيغۇ بېغىشلايدۇ.","bu kölchekning süyi tériq rengde, sirliq tuyghu béghishlaydu."]],"礮":[["古代的礮炮威力巨大。","قەدىمكى زاماندىكى توپنىڭ كۈچى ئىنتايىن زور ئىدى.","qedimki zamandiki topning küchi intayin zor idi."]],"蕮":[["这种蕮草很稀有。","بۇ خىل شىئوت ئۆسۈملۈكى ئىنتايىن ئاز ئۇچرايدۇ.","bu xil shiot ösümlüki intayin az uchraydu."]],"砮":[["考古学家在遗址中发现了古老的石砮。","ئارخېئولوگلار خارابىلىكتىن قەدىمكى تاش ئوقيا ئۇچىنى تېپىۋالدى.","arxéologlar xarabiliktin qedimki tash oqya uchini tépiwaldi."]],"袮":[["他袮着新衣服去聚会。","ئۇ يېڭى كىيىمىنى كىيىپ زىياپەتكە باردى.","u yéngi kiyimini kiyip ziyapetke bardi."]],"鄮":[["鄮山是佛教的重要圣地。","ماۋشەن بۇددا دىنىنىڭ مۇھىم مۇقەددەس جايى.","mawshen budda dinining muhim muqeddes jayi."]],"鞮":[["鞮是古代用来装饰马具的饰品。","دى قەدىمكى زاماندا ماختا-ئابدۇراسىنى زىننەتلەشكە ئىشلىتىلىدىغان زىننەت بۇيۇمى.","di qedimki zamanda maxta-abdurasini zinnetleshke ishlitilidighan zinnet buyumi."]],"鱮":[["鱮鱼肉质细腻。","شۈ بېلىقىنىڭ گۆشى نەپىس.","shü béliqining göshi nepis."]],"鯮":[["鯮鱼肉质鲜美，适合清蒸。","زۇڭ بېلىقىنىڭ گۆشى تەملىك بولۇپ، پارلاشتۇرۇپ پىشۇرۇشقا ماس كېلىدۇ.","zung béliqining göshi temlik bolup, parlashturup pishurushqa mas kélidu."]],"一笑置之":[["面对批评，他一笑置之。","تەنقىدكە دۇچ كەلگەندە، ئۇ كۈلۈپلا قويۇۋەتتى.","tenqidke duch kelgende, u külüpla qoyuwetti."]],"一是一，二是二":[["一是一，二是二，不能混淆。","بىر دېگىنى بىر، ئىككى دېگىنى ئىككى، ئارىلاشتۇرۇشقا بولمايدۇ.","bir dégini bir, ikki dégini ikki, arilashturushqa bolmaydu."]],"一本万利":[["投资这个项目一本万利。","بۇ تۈرگە مەبلەغ سالسا زور پايدا كېلىدۇ.","bu türge meblegh salsa zor payda kélidu."]],"一轮":[["一轮明月高挂在夜空中。","ئاسماندا بىر تۇتاش ئاي پارقىراپ تۇرۇپتى.","asmanda bir tutash ay parqirap turupti."]],"一语道破":[["他的一语道破，揭示了真相。","ئۇنىڭ بىر ئېغىز سۆزى ئاشكارىلىدى، ھەقىقەتنى ئاشكارىلىدى.","uning bir éghiz sözi ashkarilidi, heqiqetni ashkarilidi."]],"三段论":[["三段论是逻辑推理的一种基本形式。","ئۈچ مۇقەددىمە مەنتىقىي خۇلاسە چىقىرىشنىڭ بىر ئاساسىي شەكلىدۇر.","üch muqeddime mentiqiy xulase chiqirishning bir asasiy sheklidur."]],"三穗":[["三穗是一种优质的稻米品种。","سەنسۇي ئالاھىدە سۈپەتلىك گۈرۈچ تۈرىدۇر.","sensuy alahide süpetlik gürüch türidur."]],"三角裤衩":[["这条三角裤衩设计得很时尚。","بۇ ئۈچبۇلۇڭلۇق ئىشتاننىڭ لايىھەسى ناھايىتى مودېرن قىلىنغان.","bu üchbulungluq ishtanning layihesi nahayiti modérn qilinghan."]],"不可数":[["这些数字都是不可数的。","بۇ سانلارنىڭ ھەممىسى ساناقسىز.","bu sanlarning hemmisi sanaqsiz."]],"上相":[["这张照片上相效果很好。","بۇ سۈرەتنىڭ چۈشۈش ئۈنۈمى ناھايىتى ياخشى.","bu süretning chüshüsh ünümi nahayiti yaxshi."]],"不可分割":[["我们不可分割。","بىز ئايرىلغىلى بولمايدىغان بىر گەۋدىمىز.","biz ayrilghili bolmaydighan bir gewdimiz."]],"丁字裤":[["丁字裤是一种内衣款式，设计独特，穿着舒适。","دىڭزىكۇي بىر خىل ئىچ كىيىم ئۇسلۇبى بولۇپ، لايىھەسى ئالاھىدە، كىيگەندە راھەت.","dingzikuy bir xil ich kiyim uslubi bolup, layihesi alahide, kiygende rahet."]],"上菜秀":[["这档节目叫《上菜秀》。","تەرجىمە قىلىنغان جۈملىلەر:","terjime qilinghan jümliler:"]],"上虞市":[["上虞市是一座古城。","تەرجىمە قىلىنغان جۈملىلەر:","terjime qilinghan jümliler:"]],"不是味儿":[["这个菜完全不是味儿，太咸了。","بۇ تائامنىڭ تەمى پۈتۈنلەي يوق، بەك تۇزلۇق.","bu taamning temi pütünley yoq, bek tuzluq."]],"世胄":[["世胄继承家族荣耀。","ئەسىلزادە ئائىلە شەرىپىنى ۋارىسلىق قىلىپ داۋاملاشتۇرىدۇ.","esilzade aile sheripini warisliq qilip dawamlashturidu."]],"中国中央电视台":[["中国中央电视台是全国性的电视台。","جۇڭگو مەركىزىي تېلېۋىزىيە ئىستانسىسى پۈتۈن مەملىكەتلىك تېلېۋىزىيە ئىستانسىسى.","junggo merkiziy téléwiziye istansisi pütün memliketlik téléwiziye istansisi."]],"主体思想":[["主体思想具有深远影响。","ئىدىيەنىڭ تەسىرى چوڭقۇر.","idiyening tesiri chongqur."]],"中华田园犬":[["中华田园犬很忠诚。","جۇڭخۇا ئېتىز ئىتى ناھايىتى سادىق.","jungxua étiz iti nahayiti sadiq."]],"乍浦镇":[["乍浦镇以海鲜闻名遐迩。","جاپۇ بازىرى دېڭىز مەھسۇلاتلىرى بىلەن داڭلىق.","japu baziri déngiz mehsulatliri bilen dangliq."]],"乳汁":[["新鲜乳汁营养丰富。","يېڭى سۈتتە ئوزۇقلۇق مول.","yéngi sütte ozuqluq mol."]],"乳突":[["乳突位于头骨的侧面。","سۈت سۆڭىكى باش سۆڭىكىنىڭ يان تەرىپىدە جايلاشقان.","süt söngiki bash söngikining yan teripide jaylashqan."]],"事务繁忙":[["他事务繁忙，抽不出时间。","ئۇنىڭ ئىشلىرى ئالدىراش، ۋاقىت چىقىرالمايدۇ.","uning ishliri aldirash, waqit chiqiralmaydu."]],"二项式定理":[["二项式定理可以简化计算。","ئىككى ئەزالىق تېئورېما ھېسابلاشنى ئاددىيلاشتۇرالايدۇ.","ikki ezaliq téoréma hésablashni addiylashturalaydu."]],"二重奏":[["小提琴的二重奏非常动听。","سكىرىپكىنىڭ ئىككىلىك چالغۇسى ئىنتايىن يېقىملىق.","skiripkining ikkilik chalghusi intayin yéqimliq."]],"二十一点":[["二十一点是一种流行的纸牌游戏。","يىگىرمە بىر نۇقتا بىر خىل ئاممىباب قارت ئويۇنى.","yigirme bir nuqta bir xil ammibab qart oyuni."]],"二氧化物":[["二氧化物通常指含氧的化合物。","دىئوكسىد ئادەتتە ئوكسىگېن بار خىمىيىلىك بىرىكمىلەرنى كۆرسىتىدۇ.","dioksid adette oksigén bar ximiyilik birikmilerni körsitidu."]],"五花腌猪肉":[["五花腌猪肉是一种用五花肉制作的腌肉食品。","بەش گۈللۈك تۇزланغان چوشقا گۆشى بەش گۈللۈك گۆشتىن ياسالغان تۇزلام گۆش يېمەكلىكى.","besh güllük tuzланghan choshqa göshi besh güllük göshtin yasalghan tuzlam gösh yémekliki."]],"交互":[["系统支持用户交互操作。","سىستېما ئىشلەتكۈچىلەرنىڭ ئۆز-ئارا مۇناسىۋەتلىك مەشغۇلاتىنى قوللايدۇ.","sistéma ishletküchilerning öz-ara munasiwetlik meshghulatini qollaydu."]],"亚哈":[["小说《白鲸》中的主角叫亚哈。","«ئاق كىت» رومانىدىكى باش پېرسوناژ ئاخاب دەپ ئاتىلىدۇ.","«aq kit» romanidiki bash pérsonazh axab dep atilidu."]],"人工智能":[["人工智能改变了生活。","سۈنئىي ئەقىل تۇرمۇشنى ئۆزگەرتتى.","sün'iy eqil turmushni özgertti."]],"人工费":[["人工费占成本很大比例。","سۈنئىي ئەمگەك ھەققى چىقىمنىڭ زور نىسبىتىنى ئىگىلەيدۇ.","sün'iy emgek heqqi chiqimning zor nisbitini igileydu."]],"交角":[["两个直线的交角为90度。","ئىككى تۈز سىزىقنىڭ ئارىلىق بۇلۇڭى 90 گىرادۇس.","ikki tüz siziqning ariliq bulungi 90 giradus."]],"亮晶晶":[["宝石亮晶晶，闪闪发光。","قىممەتلىك تاش پارقىراپ، نۇر چاچىدۇ.","qimmetlik tash parqirap, nur chachidu."]],"亮闪闪":[["项链亮闪闪，十分耀眼。","مارجان ئالاقىسى يالتىراپ، ئىنتايىن كۆزنى چاقنىتىدۇ.","marjan alaqisi yaltirap, intayin közni chaqnitidu."]],"亮堂堂":[["大厅亮堂堂，格外宽敞。","زالدەك يورۇق بولۇپ، ئالاھىدە كەڭرى ئىكەن.","zaldek yoruq bolup, alahide kengri iken."]],"仁人君子":[["仁人君子总是乐于助人。","مېھرىبان ئادەملەر ھەمىشە ياردەم قىلىشقا خۇشالدۇر.","méhriban ademler hemishe yardem qilishqa xushaldur."]],"以弗所":[["以弗所是古代的重要城市。","ئېفېس قەدىمكى زاماندىكى مۇھىم شەھەر ئىدى.","éfés qedimki zamandiki muhim sheher idi."]],"伊莉莎白":[["伊莉莎白是一位优雅的女士。","ئېلىزابېت ناھايىتى نەپىس ئايال.","élizabét nahayiti nepis ayal."]],"伊通火山群":[["伊通火山群是地质奇观。","ئىتۇڭ يانار تاغ گۇرۇپپىسى گېئولوگىيەلىك مۆجىزە.","itung yanar tagh guruppisi géologiyelik möjize."]],"伍家岗":[["伍家岗是武汉的一个著名区域。","ۋۇجياگاڭ ۋۇخەننىڭ داڭلىق رايونى.","wujyagang wuxenning dangliq rayoni."]],"伢子":[["这个伢子聪明又活泼。","بۇ بالا ئەقىللىق ھەم جانلىق.","bu bala eqilliq hem janliq."]],"休谟":[["休谟是著名的哲学家。","ھيۇم مەشھۇر پەلسەپىشۇناس.","hyum meshhur pelsepishunas."]],"佉卢文":[["佉卢文是古代印度的一种文字。","خاروشتى يېزىقى قەدىمكى ھىندىستاننىڭ بىر خىل يېزىقىدۇر.","xaroshti yéziqi qedimki hindistanning bir xil yéziqidur."]],"位元组":[["这个位元组的数据需要仔细检查。","بۇ بايتتىكى سانلىق مەلۇماتلارنى ئەستايىدىل تەكشۈرۈش كېرەك.","bu bayttiki sanliq melumatlarni estayidil tekshürüsh kérek."]],"佣钱":[["佣钱每月按时发放。","ۋاكالەت ھەققى ھەر ئايدا ۋاقتىدا تارقىتىلىدۇ.","wakalet heqqi her ayda waqtida tarqitilidu."]],"伯都":[["伯都是古代部落首领。","بۇدۇخ ئەسكى زامان قەبىلە باشلىقى.","budux eski zaman qebile bashliqi."]],"俄塔社":[["俄塔社是俄罗斯的国家级通讯社。","ئىتار-تاسس ئورۇسىيەنىڭ دۆلەتلىك ئاخبارات ئاگېنتلىقى.","itar-tass orusiyening döletlik axbarat agéntliqi."]],"俗滥":[["这种老套的桥段已经俗滥不堪。","بۇ خىل كونا سېنارىيە ئاللىقاچان ئاممىۋى بولۇپ كەتتى.","bu xil kona sénariye alliqachan ammiwi bolup ketti."]],"便服":[["她穿着舒适的便服出门。","ئۇ راھەت كۈندىلىك كىيىم كىيىپ سىرتقا چىقتى.","u rahet kündilik kiyim kiyip sirtqa chiqti."]],"佳里镇":[["佳里镇以传统的工艺和美丽的自然风光而闻名。","جالى بازىرى ئەنئەنىۋى ھۈنەرۋەنچىلىكى ۋە گۈزەل تەبىئىي مەنزىرىسى بىلەن تونۇلغان.","jali baziri en'eniwi hünerwenchiliki we güzel tebiiy menzirisi bilen tonulghan."]],"使用价值":[["商品的使用价值取决于其用途。","مالنىڭ ئىشلىتىش قىممىتى ئۇنىڭ ئىشلىتىلىشىگە باغلىق.","malning ishlitish qimmiti uning ishlitilishige baghliq."]],"保八":[["他决心保八进四。","ئۇ سەككىزنى قوغداپ تۆتكە كىرىشكە بەل باغلىدى.","u sekkizni qoghdap tötke kirishke bel baghlidi."]],"保利科技有限公司":[["保利科技有限公司推出新产品。","باۋلى تېخنىكا چەكلىك شىركىتى يېڭى مەھسۇلاتنى تونۇشتۇردى.","bawli téxnika cheklik shirkiti yéngi mehsulatni tonushturdi."]],"停刊":[["杂志停刊了。","ژۇرنال نەشرى توختىتىلدى.","zhurnal neshri toxtitildi."]],"偶像剧":[["这部偶像剧吸引了大量年轻观众。","بۇ ئىدول تىياتىرى كۆپ مىقداردىكى ياش تاماشىبىنلارنى جەلپ قىلدى.","bu idol tiyatiri köp miqdardiki yash tamashibinlarni jelp qildi."]],"伪托":[["他伪托他人之名行事。","ئۇ باشقىلارنىڭ نامى بىلەن يالغان ھەرىكەت قىلدى.","u bashqilarning nami bilen yalghan heriket qildi."]],"备耕":[["农民开始备耕春季作物。","دېھقانلار باھارلىق زىرائەتلەرگە تەييارلىق قىلىشقا باشلىدى.","déhqanlar baharliq ziraetlerge teyyarliq qilishqa bashlidi."]],"备注栏":[["备注栏用于补充说明。","ئىزاھات ئىستونى قوشۇمچە چۈشەندۈرۈش ئۈچۈن ئىشلىتىلىدۇ.","izahat istoni qoshumche chüshendürüsh üchün ishlitilidu."]],"偷情":[["他们偷情被当场抓住。","ئۇلار خىيانەت قىلىۋاتقاندا ئوخشىتىلىپ تۇتۇلدى.","ular xiyanet qiliwatqanda oxshitilip tutuldi."]],"偷猎者":[["偷猎者破坏了生态平衡。","يوشۇرۇن ئوۋچىلار ئېكولوگىيەلىك تەڭپۇڭلۇقنى بۇزدى.","yoshurun owchilar ékologiyelik tengpungluqni buzdi."]],"催婚":[["家人开始催婚。","ئائىلە ئەزالىرى توي قىلىشقا ئالدىرىتىشقا باشلىدى.","aile ezaliri toy qilishqa aldiritishqa bashlidi."]],"伤不起":[["这种压力真是让人伤不起。","بۇ خىل بېسىم ھەقىقەتەن چىداپ بولغۇسىز.","bu xil bésim heqiqeten chidap bolghusiz."]],"像话":[["这样说话太不像话了！","بۇنداق سۆزلەش ئىنتايىن ئەپسۇسسىز!","bundaq sözlesh intayin epsussiz!"]],"伤寒":[["他感染了伤寒需要隔离治疗。","ئۇ تىف بىلەن يۇقۇملىنىپ، ئايرىپ داۋالاشقا ئېھتىياجلىق.","u tif bilen yuqumlinip, ayrip dawalashqa éhtiyajliq."]],"伤心蒿目":[["面对苦难，他感到伤心蒿目。","جاپا-مۇشەققەتكە دۇچ كەلگەندە، ئۇ كۆڭلى ئاغرىپ، كۆزى ياشلىنىدۇ.","japa-musheqqetke duch kelgende, u köngli aghrip, közi yashlinidu."]],"光荣革命":[["光荣革命是英国历史上的重要事件。","شەرەپلىك ئىنقىلاب ئەنگلىيە تارىخىدىكى مۇھىم ۋەقەدۇر.","shereplik inqilab engliye tarixidiki muhim weqedur."]],"先父":[["先父曾教导我做人之道。","ئالدىنقى ئاتام ماڭا ئادەم بولۇش يولىنى ئۆگەتكەن.","aldinqi atam manga adem bolush yolini ögetken."]],"光接收器":[["光接收器能捕捉光信号。","يورۇقلۇق قوبۇللىغۇچ يورۇقلۇق سىگنالىنى تۇتالايدۇ.","yoruqluq qobullighuch yoruqluq signalini tutalaydu."]],"光阴荏苒":[["光阴荏苒，青春不再回头。","ۋاقىت ئۆتۈپ تۇرىدۇ، ياشلىق ئەمدى قايتىپ كەلمەيدۇ.","waqit ötüp turidu, yashliq emdi qaytip kelmeydu."]],"克东县":[["克东县以农业为主要产业。","كېدۇڭ ناھىيىسىنىڭ ئاساسلىق تارمىقى يېزا ئىگىلىكى.","kédung nahiyisining asasliq tarmiqi yéza igiliki."]],"两相情愿":[["这件事需要两相情愿才能成功。","بۇ ئىش ئىككى تەرەپنىڭ رازىلىقى بىلەن ئاندىن مۇۋەپپەقىيەت قازىنالايدۇ.","bu ish ikki terepning raziliqi bilen andin muweppeqiyet qazinalaydu."]],"入关":[["货物通过入关检查。","يۈكلەر تاموژنىدىن تەكشۈرۈشتىن ئۆتتى.","yükler tamozhnidin tekshürüshtin ötti."]],"公买公卖":[["交易必须公买公卖，公平合理。","سودا چوقۇم ئوچۇق سېتىش-سېتىۋېلىش، ئادىل ۋە مۇۋاپىق بولۇشى كېرەك.","soda choqum ochuq sétish-sétiwélish, adil we muwapiq bolushi kérek."]],"公路网":[["国家公路网覆盖全国。","دۆلەت تاشيول تورى پۈتۈن مەملىكەتنى قاپلىدى.","dölet tashyol tori pütün memliketni qaplidi."]],"八方":[["八方指东南西北及四个角落。","سەككىز تەرەپ شەرق جەنۇب غەرب شىمال ۋە تۆت بۇلۇڭنى كۆرسىتىدۇ.","sekkiz terep sherq jenub gherb shimal we töt bulungni körsitidu."]],"六扇门":[["六扇门是古代神秘的机构。","ئالتە ئىشىك قەدىمكى زاماننىڭ سىرلىق ئورگىنى ئىدى.","alte ishik qedimki zamanning sirliq orgini idi."]],"再一次":[["请再一次尝试。","يەنە بىر قېتىم سىناپ بېقىڭ.","yene bir qétim sinap béqing."]],"再四":[["再四强调，这个问题必须重视。","قايتا-قايتا تەكىتلەيمەنكى، بۇ مەسىلىگە چوقۇم ئەھمىيەت بېرىش كېرەك.","qayta-qayta tekitleymenki, bu mesilige choqum ehmiyet bérish kérek."]],"再赛":[["明天将进行决赛的再赛。","ئەتە ھەل قىلغۇچ مۇسابىقىنىڭ قايتا مۇسابىقىسى ئۆتكۈزۈلىدۇ.","ete hel qilghuch musabiqining qayta musabiqisi ötküzülidu."]],"公司债":[["公司债的利率通常较低。","شىركەت زايومىنىڭ ئۆسۈم نىسبىتى ئادەتتە بىر قەدەر تۆۋەن.","shirket zayomining ösüm nisbiti adette bir qeder töwen."]],"再转复":[["心脏成功实现了再转复。","يۈرەك قايتا رېتىمگە مۇۋەپپەقىيەتلىك كەلتۈرۈلدى.","yürek qayta rétimge muweppeqiyetlik keltürüldi."]],"冒着":[["冒着大雨，他们终于赶到了目的地。","قېتىق يامغۇردا، ئۇلار ئاخىرى مەنزىلگە يېتىپ باردى.","qétiq yamghurda, ular axiri menzilge yétip bardi."]],"兵权":[["皇帝牢牢掌控着兵权。","ئىمپېراتور ھەربىي ھوقۇقنى چىڭ كونترول قىلىدۇ.","impérator herbiy hoquqni ching kontrol qilidu."]],"兵精粮足":[["军队兵精粮足，士气高昂。","ئارمىيەنىڭ ئەسكەرلىرى ماھىر، ئوزۇق-تۈلۈكى مول، روھى يۇقىرى.","armiyening eskerliri mahir, ozuq-tülüki mol, rohi yuqiri."]],"冥想":[["冥想有助于缓解压力。","كۆرۈنمەس ئويلىنىش بېسىمنى يېنىكلىتىشكە ياردەم قىلىدۇ.","körünmes oylinish bésimni yéniklitishke yardem qilidu."]],"凌空":[["飞机凌空飞过天际。","ئايروپىلان ئاسماندا لەپىلدەپ ئۇچتى.","ayropilan asmanda lepildep uchti."]],"出生地点":[["出生地点记录在档案里。","تۇغۇلغان يەر ئارخىپتا خاتىرىلەنگەن.","tughulghan yer arxipta xatirilengen."]],"刑期":[["刑期通常为几年。","جازا مۇددىتى ئادەتتە بىر نەچچە يىل بولىدۇ.","jaza mudditi adette bir nechche yil bolidu."]],"冰塞":[["冰塞导致河流无法流动。","مۇز توسۇق دەريانىڭ ئېقىشىغا توسالغۇ بولىدۇ.","muz tosuq deryaning éqishigha tosalghu bolidu."]],"列王记上":[["《列王记上》详细描述了大卫王的事迹。","《پادىشاھلار 1-كىتابىدا》داۋۇت پادىشاھنىڭ ئىش-ئەمەللىرى تەپسىلىي تەسۋىرلەنگەن.","《padishahlar 1-kitabida》dawut padishahning ish-emelliri tepsiliy teswirlengen."]],"到什么山上，唱什么歌":[["到什么山上，唱什么歌。","قايسى تاغقا بارساڭ، شۇ تاغنىڭ ناخشىسىنى ئېيت.","qaysi taghqa barsang, shu taghning naxshisini éyt."]],"利纳克斯":[["利纳克斯是开源操作系统的先驱。","لىنۇكس ئوچۇق كودلۇق مەشغۇلات سىستېمىسىنىڭ ئالدىنقىسى.","linuks ochuq kodluq meshghulat sistémisining aldinqisi."]],"刘少奇":[["刘少奇是中国共产党的领导人。","لىۇ شاۋچى جۇڭگو كوممۇنىستىك پارتىيەسىنىڭ رەھبىرى.","liu shawchi junggo kommunistik partiyesining rehbiri."]],"力矩":[["力矩是物理学中的重要概念。","كۈچ مومېنتى فىزىكىدىكى مۇھىم ئۇقۇم.","küch moménti fizikidiki muhim uqum."]],"加强针":[["加强针能提升免疫效果。","كۈچەيتىش ئوكۇمى ئىممۇنىتېت ئۈنۈمىنى ئۆستۈرىدۇ.","kücheytish okumi immunitét ünümini östüridu."]],"加达里":[["加达里是一个古老的文明。","كالدالىق قەدىمىي بىر مەدەنىيەتتۇر.","kaldaliq qedimiy bir medeniyettur."]],"创利":[["项目带来了可观的创利。","تۈر كۆرۈنەرلىك پايدا ئېلىپ كەلدى.","tür körünerlik payda élip keldi."]],"创业投资":[["创业投资是高风险高回报的领域。","ئىجادىيەت مەبلەغ سېلىش يۇقىرى خەتەر ۋە يۇقىرى كىرىملىك ساھە.","ijadiyet meblegh sélish yuqiri xeter we yuqiri kirimlik sahe."]],"功莫大焉":[["此功莫大焉！","بۇ تۆھپە ئىنتايىن زور!","bu töhpe intayin zor!"]],"勒杀":[["敌人试图勒杀他。","دۈشمەن ئۇنى بوغۇپ ئۆلتۈرمەكچى بولدى.","düshmen uni boghup öltürmekchi boldi."]],"劝诫":[["古人常以诗书劝诫后人。","قەدىمكىلەر كۆپىنچە شېئىر-كىتاب ئارقىلىق كېيىنكى ئەۋلادلارغا نەسىھەت قىلغان.","qedimkiler köpinche shéir-kitab arqiliq kéyinki ewladlargha nesihet qilghan."]],"化学疗法":[["医生采用化学疗法治疗癌症患者。","دوختۇرلار راك كېسىلىگە گىرىپتار بولغانلارنى خىمىيىلىك داۋالاش ئۇسۇلى بىلەن داۋالايدۇ.","doxturlar rak késilige giriptar bolghanlarni ximiyilik dawalash usuli bilen dawalaydu."]],"匡扶社稷":[["他立志要匡扶社稷，安定天下。","ئۇ دۆلەتنى قوغداپ، دۇنيانى تىنچلاندۇرۇشقا بەل باغلىدى.","u döletni qoghdap, dunyani tinchlandurushqa bel baghlidi."]],"千金":[["他继承了一笔千金遗产。","ئۇ مىڭ ئالتۇنلۇق مىراسقا ۋارىسلىق قىلدى.","u ming altunluq mirasqa warisliq qildi."]],"半圆仪":[["半圆仪是测量弧长的工具。","يېرىم چەمبەر ئۆلچىگۈچ يەينىڭ ئۇزۇنلۇقىنى ئۆلچەيدىغان ئەسۋابتۇر.","yérim chember ölchigüch yeyning uzunluqini ölcheydighan eswabtur."]],"南北美":[["南北美洲相连。","جەنۇبىي ۋە شىمالىي ئامېرىكا تۇتىشىدۇ.","jenubiy we shimaliy amérika tutishidu."]],"午时":[["午时正对应中午十二点。","چۈش ۋاقتى چۈشلۈك سائەت ئون ئىككىگە توغرا كېلىدۇ.","chüsh waqti chüshlük saet on ikkige toghra kélidu."]],"南部县":[["南部县以丰富的矿产资源闻名。","جەنۇبىي ناھىيە باي مىنېرال بايلىقلىرى بىلەن داڭلىق.","jenubiy nahiye bay minéral bayliqliri bilen dangliq."]],"博士生":[["这位博士生正在撰写他的毕业论文。","بۇ دوكتورلۇق ئوقۇغۇچىسى ئۆزىنىڭ ئوقۇش پۈتتۈرۈش ئىلمىي ماقالىسىنى يېزىۋاتىدۇ.","bu doktorluq oqughuchisi özining oqush püttürüsh ilmiy maqalisini yéziwatidu."]],"博弈":[["这场博弈充满了悬念。","بۇ ئويۇن تولۇق سەۋەنلىككە تولغان.","bu oyun toluq sewenlikke tolghan."]],"去掉":[["请把这个错误去掉。","بۇ خاتالىقنى تۈزىتىڭ.","bu xataliqni tüziting."]],"反叛":[["他因反叛被流放到边疆。","ئۇ خىيانەت قىلغانلىقى ئۈچۈن چېگرا بويىغا سۈرگۈن قىلىندى.","u xiyanet qilghanliqi üchün chégra boyigha sürgün qilindi."]],"反之亦然":[["反之亦然，同样成立。","ئەكسىچە بولغاندا ھەم شۇنداق، ئوخشاشلا ئورۇنلۇق.","eksiche bolghanda hem shundaq, oxshashla orunluq."]],"即溶咖啡":[["即溶咖啡冲泡简单快捷。","ئېرىيدىغان قەھۋە دەملەش ئاددىي ۋە تېز.","ériydighan qehwe demlesh addiy we téz."]],"卡拉胶":[["卡拉胶常用于制作果冻和糖果。","كاراگېن كۆپىنچە جېلە ۋە كەمپۈت ياساشتا ئىشلىتىلىدۇ.","karagén köpinche jéle we kempüt yasashta ishlitilidu."]],"口湖乡":[["口湖乡风景优美。","ئېغىز كۆل يېزىسىنىڭ مەنزىرىسى گۈزەل.","éghiz köl yézisining menzirisi güzel."]],"可好":[["今天天气可好！","بۈگۈن ھاۋا بەك ياخشى!","bügün hawa bek yaxshi!"]],"古今韵会举要":[["《古今韵会举要》是重要的韵书。","«قەدىمكى ۋە ھازىرقى رىم-ئاھەڭلەرنىڭ مۇھىم مەزمۇنى» مۇھىم رىم-ئاھەڭ كىتابى.","«qedimki we hazirqi rim-ahenglerning muhim mezmuni» muhim rim-aheng kitabi."]],"台州":[["台州以美食闻名。","تەيجۇ تائاملىرى بىلەن داڭلىق.","teyju taamliri bilen dangliq."]],"史传":[["这部史传记录了古代事件。","بۇ تارىخىي رىۋايەت قەدىمكى ۋەقەلەرنى خاتىرىلىگەن.","bu tarixiy riwayet qedimki weqelerni xatiriligen."]],"右江区":[["右江区是这座城市的一个行政区。","يۇجياڭ رايونى بۇ شەھەرنىڭ بىر مەمۇرىي رايونى.","yujyang rayoni bu sheherning bir memuriy rayoni."]],"吉普斯夸":[["吉普斯夸是一个古老的城镇。","جىپۇسكۇا بىر قەدىمىي شەھەرچە.","jipuskua bir qedimiy sheherche."]],"吃角子老虎":[["他在赌场玩吃角子老虎机。","ئۇ قىمارخانىدا قىمار ئويۇنى ئوينايدۇ.","u qimarxanida qimar oyuni oynaydu."]],"各奔前程":[["毕业后，大家各奔前程。","ئوقۇش پۈتكۈزگەندىن كېيىن، ھەممە كىشى ئۆز يولىغا ماڭىدۇ.","oqush pütküzgendin kéyin, hemme kishi öz yoligha mangidu."]],"合叶":[["机械零件的合叶要精准。","مېخانىكىلىق زاپچاسلارنىڭ تۇتاشتۇرغۇچىسى ئېنىق بولۇشى كېرەك.","méxanikiliq zapchaslarning tutashturghuchisi éniq bolushi kérek."]],"吉林":[["吉林是中国东北部的省份。","جىلىن جۇڭگونىڭ شەرقىي شىمالىدىكى ئۆلكە.","jilin junggoning sherqiy shimalidiki ölke."]],"吊盐水":[["医生给他吊盐水治疗脱水。","دوختۇر ئۇنىڭغا سۇسىزلىنىشىنى داۋالاش ئۈچۈن فىزىئولوگىيەلىك تۇز سۇيى قۇيدى.","doxtur uninggha susizlinishini dawalash üchün fiziologiyelik tuz suyi quydi."]],"同人":[["同人作品基于原有故事创作。","ئوخشاش ئەسەرلەر ئەسلى ھېكايە ئاساسىدا ئىجاد قىلىنىدۇ.","oxshash eserler esli hékaye asasida ijad qilinidu."]],"名媛":[["她是一位优雅的名媛。","ئۇ نەپىس بىر داڭلىق ئايال.","u nepis bir dangliq ayal."]],"名义上":[["名义上他是公司的股东。","نامى جەھەتتىن ئۇ شىركەتنىڭ پايچىكى.","nami jehettin u shirketning paychiki."]],"吡咯":[["吡咯是有机化学中的环状结构。","پىرول ئورگانىك خىمىيەدىكى ھالقىسىمان قۇرۇلما.","pirol organik ximiyediki halqisiman qurulma."]],"名存实亡":[["这家公司早已名存实亡。","بۇ شىركەت ئاللىبۇرۇن ئىسىمى بار، جىسمى يوق ھالەتكە چۈشۈپ قالغان.","bu shirket alliburun isimi bar, jismi yoq haletke chüshüp qalghan."]],"吴桥县":[["吴桥县位于河北省东南部。","ۋۇچياۋ ناھىيىسى خېبېي ئۆلكىسىنىڭ شەرقىي جەنۇبىدا جايلاشقان.","wuchyaw nahiyisi xébéy ölkisining sherqiy jenubida jaylashqan."]],"和盘托出":[["他将自己所有的计划和盘托出。","ئۇ ئۆزىنىڭ بارلىق پىلانلىرىنى ئوتتۇرىغا قويدى.","u özining barliq pilanlirini otturigha qoydi."]],"含油":[["这层岩石具有含油特性。","بۇ قاتلام تاشنىڭ نېفىت تەركىبى بار.","bu qatlam tashning néfit terkibi bar."]],"呢子":[["这件呢子大衣保暖又时尚。","بۇ يۇڭ پالتو ئىسسىق تۇتۇپلا قالماي، زامانىۋىي ئىدى.","bu yung palto issiq tutupla qalmay, zamaniwiy idi."]],"咬定":[["他咬定这个观点，不愿改变。","ئۇ بۇ كۆز قاراشنى چىڭ تۇتۇپ، ئۆزگەرتىشنى خالىمىدى.","u bu köz qarashni ching tutup, özgertishni xalimidi."]],"商水":[["商水是一种古老的饮品。","شاڭشۈي قەدىمىي بىر ئىچىملىك.","shangshüy qedimiy bir ichimlik."]],"品族":[["这个品族以追求精致生活闻名。","بۇ ئۇرۇق نەسىل نەپىس تۇرمۇشنى ئىزدىنىش بىلەن داڭلىق.","bu uruq nesil nepis turmushni izdinish bilen dangliq."]],"喜鹊":[["喜鹊在枝头欢快地歌唱。","سېغىزغان شاختا بېشىدا خۇشال سايرايدۇ.","séghizghan shaxta béshida xushal sayraydu."]],"喝茫":[["他喝茫了，连路都走不稳。","ئۇ ھاراققا مەست بولۇپ، يولدا تۇرالماي قالدى.","u haraqqa mest bolup, yolda turalmay qaldi."]],"丧魂失魄":[["他吓得丧魂失魄。","ئۇ قورقۇپ ھوشىدىن كەتتى.","u qorqup hoshidin ketti."]],"单元格":[["表格中的每个单元格都可以输入数据。","جەدۋەلدىكى ھەر بىر كاتەككە سانلىق مەلۇمات كىرگۈزگىلى بولىدۇ.","jedweldiki her bir katekke sanliq melumat kirgüzgili bolidu."]],"单瓣":[["这朵花只有单瓣。","بۇ گۈلدە پەقەت يالغۇز گۈل ياپرىقى بار.","bu gülde peqet yalghuz gül yapriqi bar."]],"呕吐物":[["呕吐物要清理干净。","قۇسۇقنى تازىلاپ تاشلاش كېرەك.","qusuqni tazilap tashlash kérek."]],"唢呐":[["他吹起唢呐，声音洪亮。","ئۇ سۇناينى چالدى، ئاۋازى ياڭرىدى.","u sunayni chaldi, awazi yangridi."]],"嘴牢":[["他嘴牢，守得住秘密。","ئۇنىڭ ئاغزى چىڭ، سىرنى ساقلاپ قالالايدۇ.","uning aghzi ching, sirni saqlap qalalaydu."]],"喷溅":[["油漆喷溅到墙壁上。","بوياق تامغا چېچىلىپ كەتتى.","boyaq tamgha chéchilip ketti."]],"喷丝头":[["喷丝头决定了纤维的粗细。","پۈركۈش باشلىقى تالانىڭ توم-ئىنچىكىلىكىنى بەلگىلەيدۇ.","pürküsh bashliqi talaning tom-inchikilikini belgileydu."]],"严惩不贷":[["无论身份如何，违法必究，严惩不贷。","ئورنى قانداق بولۇشىدىن قەتئىينەزەر، قانۇنغا خىلاپلىق قىلغان بولسا چوقۇم سۈرۈشتۈرۈلىدۇ، قاتتىق جازالىنىدۇ.","orni qandaq bolushidin qet'iynezer, qanungha xilapliq qilghan bolsa choqum sürüshtürülidu, qattiq jazalinidu."]],"四大天王":[["四大天王是佛教神话中的护法神。","تۆت چوڭ پادىشاھ بۇددا مىفولوگىيەسىدىكى قوغدىغۇچى ئىلاھتۇر.","töt chong padishah budda mifologiyesidiki qoghdighuchi ilahtur."]],"四乙基铅中毒":[["四乙基铅中毒很危险。","تۆت ئېتىل قوغۇشۇن زەھەرلىنىشى ئىنتايىن خەتەرلىك.","töt étil qoghushun zeherlinishi intayin xeterlik."]],"回铃音":[["设置回铃音提醒。","قايتۇرما قوڭغۇراق ئاۋازىنى تەڭشەڭ.","qayturma qongghuraq awazini tengsheng."]],"国家级":[["这个项目获得国家级认可。","بۇ تۈر دۆلەت دەرىجىلىك ئېتىراپقا ئېرىشتى.","bu tür dölet derijilik étirapqa érishti."]],"国际民间组织":[["国际民间组织在促进国际合作方面发挥重要作用。","خەلقئارا پۇقراۋى تەشكىلاتلار خەلقئارا ھەمكارلىقنى ئىلگىرى سۈرۈشتە مۇھىم رول ئوينايدۇ.","xelq'ara puqrawi teshkilatlar xelq'ara hemkarliqni ilgiri sürüshte muhim rol oynaydu."]],"国际笔会":[["国际笔会促进各国作家之间的文化交流。","خەلقئارا قەلەم تەشكىلاتى ھەر قايسى دۆلەت يازغۇچىلىرى ئارىسىدىكى مەدەنىيەت ئالماشتۇرۇشنى ئىلگىرى سۈرىدۇ.","xelq'ara qelem teshkilati her qaysi dölet yazghuchiliri arisidiki medeniyet almashturushni ilgiri süridu."]],"国际航空联合会":[["国际航空联合会制定了安全标准。","خەلقئارا ئاۋىياتسىيە بىرلەشمىسى بىخەتەرلىك ئۆلچىمىنى بەلگىلىدى.","xelq'ara awiyatsiye birleshmisi bixeterlik ölchimini belgilidi."]],"图们":[["图们江流经多个城市。","تۇمەن دەرياسى بىر قانچە شەھەردىن ئېقىپ ئۆتىدۇ.","tumen deryasi bir qanche sheherdin éqip ötidu."]],"图西族":[["图西族是非洲的一个民族。","تۇتسى مىللىتى ئافرىقىدىكى بىر مىللەت.","tutsi milliti afriqidiki bir millet."]],"围拢":[["人群逐渐围拢过来，好奇地观看。","ئادەملەر ئاستا-ئاستا قورشىلىپ كېلىپ، قىزىقىپ كۆردى.","ademler asta-asta qorshilip kélip, qiziqip kördi."]],"国际原子能机构":[["国际原子能机构监督核能安全。","خەلقئارا ئاتوم ئېنېرگىيە ئورگىنى يادرو ئېنېرگىيە بىخەتەرلىكىنى نازارەت قىلىدۇ.","xelq'ara atom énérgiye orgini yadro énérgiye bixeterlikini nazaret qilidu."]],"土语":[["土语通常指特定地区的口语表达。","توپا تىل ئادەتتە مەلۇم رايوننىڭ ئېغىز تىلى ئىپادىسىنى كۆرسىتىدۇ.","topa til adette melum rayonning éghiz tili ipadisini körsitidu."]],"地痞":[["地痞流氓经常扰乱社会秩序。","يەر ئاستى بۇزغۇنچىلار جەمئىيەت تەرتىپىنى دائىم بۇزىدۇ.","yer asti buzghunchilar jem'iyet tertipini daim buzidu."]],"国手":[["国手代表国家参加国际比赛。","دۆلەت ماھىرى دۆلەت نامىدىن خەلقئارا مۇسابىقىلەرگە قاتنىشىدۇ.","dölet mahiri dölet namidin xelq'ara musabiqilerge qatnishidu."]],"地质学":[["地质学是研究地球物质组成和演化的学科。","گېئولوگىيە يەر شارىنىڭ ماددا تەركىبى ۋە تەرەققىياتىنى تەتقىق قىلىدىغان پەن.","géologiye yer sharining madda terkibi we tereqqiyatini tetqiq qilidighan pen."]],"地动山摇":[["地震时地动山摇。","يەر تەۋرىگەندە يەر تەۋرىنىپ تاغ لەۋزىدە بولىدۇ.","yer tewrigende yer tewrinip tagh lewzide bolidu."]],"坡路":[["这条坡路非常难走。","بۇ يانتۇ يول مېڭىش ناھايىتى قىيىن.","bu yantu yol méngish nahayiti qiyin."]],"城楼":[["城楼是古代防御的重要设施。","شەھەر قورغىنى قەدىمكى دەۋرلەردىكى مۇداپىئەنىڭ مۇھىم ئەسلىھەسى ئىدى.","sheher qorghini qedimki dewrlerdiki mudapiening muhim eslihesi idi."]],"执念":[["他对成功有强烈的执念。","ئۇنىڭ مۇۋەپپەقىيەتكە بولغان قەتئىي ئىرادىسى كۈچلۈك.","uning muweppeqiyetke bolghan qet'iy iradisi küchlük."]],"执政方式":[["民主执政方式更透明。","دېموكراتىك ھاكىمىيەت يۈرگۈزۈش ئۇسۇلى تېخىمۇ شەفاف.","démokratik hakimiyet yürgüzüsh usuli téximu shefaf."]],"基质膜":[["基质膜用于保护细胞结构。","ئاساسىي مېمبرانا ھۈجەيرە قۇرۇلمىسىنى قوغداشقا ئىشلىتىلىدۇ.","asasiy mémbrana hüjeyre qurulmisini qoghdashqa ishlitilidu."]],"堂而皇之":[["他堂而皇之地说出了自己的看法。","ئۇ جىيەنئەرچىلەپ ئۆز قارىشىنى ئېيتتى.","u jiyen'erchilep öz qarishini éytti."]],"坚戈":[["这是一种古老的坚戈武器。","بۇ قەدىمىي جىيەنگې قورالى.","bu qedimiy jiyengé qorali."]],"士林区":[["士林区是台北市的一个行政区。","شىلىن رايونى تەيبېي شەھىرىنىڭ بىر مەمۇرىي رايونى.","shilin rayoni teybéy shehirining bir memuriy rayoni."]],"壑沟":[["壑沟之间形成了天然的屏障。","ئېرىق-ئۆستەڭلەر ئارىسىدا تەبىئىي توساق شەكىللەنگەن.","ériq-östengler arisida tebiiy tosaq shekillengen."]],"坚若磐石":[["他的信念坚若磐石，不可动摇。","ئۇنىڭ ئېتىقادى تاشقا ئوخشاش مۇستەھكەم، تەۋرەتمەك مۇمكىن ئەمەس.","uning étiqadi tashqa oxshash mustehkem, tewretmek mumkin emes."]],"多哈":[["多哈是卡塔尔的首都。","دەۋھا قاتارنىڭ پايتەختىدۇر.","dewha qatarning paytextidur."]],"梦魔":[["梦魔让人在梦中感到恐惧。","چۈش ئەھۋالى كىشىنى چۈشتە قورقۇنچقا سالىدۇ.","chüsh ehwali kishini chüshte qorqunchqa salidu."]],"夜惊":[["他被突如其来的夜惊吵醒。","ئۇ تۇيۇقسىز كەلگەن كېچىلىك قورقۇنچ بىلەن ئويغىنىپ كەتتى.","u tuyuqsiz kelgen kéchilik qorqunch bilen oyghinip ketti."]],"大洋洲":[["大洋洲有许多独特的动植物。","ئوكيانىيەدە نۇرغۇن ئۆزگىچە ئۆسۈملۈك ۋە ھايۋانلار بار.","okyaniyede nurghun özgiche ösümlük we haywanlar bar."]],"大月氏":[["大月氏是古代西北的一个民族。","دايۈەجى قەدىمكى زاماندىكى شىمالىي غەربتىكى بىر مىللەت ئىدى.","dayüeji qedimki zamandiki shimaliy gherbtiki bir millet idi."]],"多晶片模组":[["多晶片模组提升了芯片的集成度。","پولىكرىستاللىق چىپ مودۇلى چىپنىڭ يىغىلىش دەرىجىسىنى ئۆستۈردى.","polikristalliq chip moduli chipning yighilish derijisini östürdi."]],"大肚乡":[["大肚乡以盛产水果闻名。","چوڭ قورساق يېزىسى مېۋە-چېۋىسىنىڭ مول بولۇشى بىلەن داڭلىق.","chong qorsaq yézisi méwe-chéwisining mol bolushi bilen dangliq."]],"大量杀伤武器":[["大量杀伤武器必须严格管控。","كۆپ مىقداردا ئۆلتۈرۈش قورالى قاتتىق كونترول قىلىنىشى كېرەك.","köp miqdarda öltürüsh qorali qattiq kontrol qilinishi kérek."]],"大韩民国":[["大韩民国是朝鲜半岛的国家。","داھان جۇمھۇرىيىتى كورېيە يېرىم ئارىلىدىكى دۆلەت.","dahan jumhuriyiti koréye yérim arilidiki dölet."]],"夫子自道":[["夫子自道形容自夸。","فۇزى ئۆزىنى ماختاشنى تەسۋىرلەيدۇ.","fuzi özini maxtashni teswirleydu."]],"夫役":[["夫役是古代的劳役制度。","فۇيە قەدىمكى دەۋردىكى ئەمگەك مەجبۇرىيىتى تۈزۈمى.","fuye qedimki dewrdiki emgek mejburiyiti tüzümi."]],"失势":[["他失势后，昔日的朋友都疏远了他。","ئۇ ھوقۇقىنى يوقاتقاندىن كېيىن، ئىلگىرىكى دوستلىرى ئۇنىڭدىن يىراقلاشتى.","u hoquqini yoqatqandin kéyin, ilgiriki dostliri uningdin yiraqlashti."]],"天价":[["这套房子标价真是天价。","بۇ ئۆينىڭ باھاسى ھەقىقەتەن ئاسمان باھاسى ئىكەن.","bu öyning bahasi heqiqeten asman bahasi iken."]],"天冷":[["天冷的时候要多穿点衣服。","ھاۋا سوغۇق بولغاندا كۆپرەك كىيىم كىيىش كېرەك.","hawa soghuq bolghanda köprek kiyim kiyish kérek."]],"大鲵":[["大鲵是现存最古老的两栖动物之一。","چوڭ سۇ كېسەللىكى ھازىرغىچە مەۋجۇت بولغان ئەڭ قەدىمىي ئىككى خىل ياشايدىغان ھايۋانلارنىڭ بىرى.","chong su késelliki hazirghiche mewjut bolghan eng qedimiy ikki xil yashaydighan haywanlarning biri."]],"奔走相告":[["大家奔走相告。","ھەممەيلەن يۈگۈرۈشۈپ بىر-بىرىگە خەۋەر بەردى.","hemmeylen yügürüshüp bir-birige xewer berdi."]],"奕䜣":[["奕䜣是清朝的重要人物。","ئىشىن ئەلبېتە چىڭ سۇلالىسىنىڭ مۇھىم شەخسى.","ishin elbéte ching sulalisining muhim shexsi."]],"奸官污吏":[["奸官污吏鱼肉百姓。","زالىم ئەمەلدارلار خەلقنى ئېزىپ ئاستىدى.","zalim emeldarlar xelqni ézip astidi."]],"奶汤":[["奶汤面味道鲜美又营养。","سۈتلۈك شورپا تەملىك ۋە ئوزۇقلۇققا باي.","sütlük shorpa temlik we ozuqluqqa bay."]],"好手":[["他是这个领域的好手。","ئۇ بۇ ساھەنىڭ ماھىرى.","u bu sahening mahiri."]],"奶酪火锅":[["奶酪火锅是瑞士的传统美食。","چىز قازانچىسى شىۋېتسىيەنىڭ ئەنئەنىۋى تائامى.","chiz qazanchisi shiwétsiyening en'eniwi taami."]],"好友":[["我和他是多年的好友，关系非常密切。","مەن ئۇنىڭ بىلەن كۆپ يىللىق يېقىن دوست، مۇناسىۋىتىمىز بەك يېقىن.","men uning bilen köp yilliq yéqin dost, munasiwitimiz bek yéqin."]],"好吃懒做":[["他好吃懒做，整天无所事事。","ئۇ يېيىشكە ماھىر، ئىشلەشكە يالغاق، كۈن بويى بىكار يۈرىدۇ.","u yéyishke mahir, ishleshke yalghaq, kün boyi bikar yüridu."]],"字句":[["他写了一个精彩的字句。","ئۇ بىر ئېسىل جۈملىنى يازدى.","u bir ésil jümlini yazdi."]],"孢子":[["孢子是真菌繁殖的重要结构。","سپورا زەمبۇرۇغلارنىڭ كۆپىيىشىدىكى مۇھىم قۇرۇلما.","spora zemburughlarning köpiyishidiki muhim qurulma."]],"孤寒":[["孤寒的孩子需要社会的帮助。","يالغۇز ۋە مۇزدەك بالىغا جەمئىيەتنىڭ ياردىمى كېرەك.","yalghuz we muzdek baligha jem'iyetning yardimi kérek."]],"嫖资":[["嫖资的数额令人震惊。","پاھىشىۋازلىق ھەققىنىڭ مىقدارى كىشىنى ھەيران قالدۇرىدۇ.","pahishiwazliq heqqining miqdari kishini heyran qalduridu."]],"守时":[["他守时，从不迟到。","ئۇ ۋاقىتقا رىئايە قىلىدۇ، ھەرگىز كېچىكمەيدۇ.","u waqitqa riaye qilidu, hergiz kéchikmeydu."]],"安国市":[["安国市位于河北省中部。","ئەنگو شەھىرى خېبېي ئۆلكىسىنىڭ مەركىزىدە جايلاشقان.","engo shehiri xébéy ölkisining merkizide jaylashqan."]],"安多县":[["安多县位于西藏高原，气候独特。","ئامدو ناھىيىسى تىبەت ئېگىزلىكىدە جايلاشقان بولۇپ، ئىقلىمى ئالاھىدە.","amdo nahiyisi tibet égizlikide jaylashqan bolup, iqlimi alahide."]],"安南":[["安南是越南历史上的一个地区。","ئەننەن ۋىيېتنام تارىخىدىكى بىر رايون.","ennen wiyétnam tarixidiki bir rayon."]],"官老爷":[["官老爷们总是高高在上。","ئەمەلدار ئەپەندىلەر ھەمىشە ئۆزىنى ئۈستۈن تۇتىدۇ.","emeldar ependiler hemishe özini üstün tutidu."]],"客源":[["稳定的客源是餐厅持续经营的关键。","مۇقىم مېھمان مەنبەسى رېستوراننىڭ داۋاملىق تىجارەت قىلىشىنىڭ ئاچقۇچىدۇر.","muqim méhman menbesi réstoranning dawamliq tijaret qilishining achquchidur."]],"定案":[["案件最终定案。","دەۋا ئاخىرىدا ھۆكۈم قىلىندى.","dewa axirida höküm qilindi."]],"家丑不可外传，流言切莫轻信":[["家丑不可外传，流言切莫轻信。","ئائىلە ئېيىبىنى سىرتقا تارقاتقىلى بولمايدۇ، ئېغىز-ئېغىز سۆزلەرگە ئىشەنمەسلىك كېرەك.","aile éyibini sirtqa tarqatqili bolmaydu, éghiz-éghiz sözlerge ishenmeslik kérek."]],"家用电脑":[["家用电脑是学习和工作的重要工具。","ئائىلە كومپيۇتېرى ئۆگىنىش ۋە خىزمەتنىڭ مۇھىم قورالى.","aile kompyutéri öginish we xizmetning muhim qorali."]],"密致":[["他的文笔风格密致细腻。","ئۇنىڭ يازغۇچىلىق ئۇسلۇبى زىچ ۋە نەپىس ئىدى.","uning yazghuchiliq uslubi zich we nepis idi."]],"宿雾语":[["这种宿雾语在当地流传已久。","بۇ خىل قويۇق تۇمان تىلى يەرلىكتە ئۇزۇندىن بۇيان تارقالماقتا.","bu xil qoyuq tuman tili yerlikte uzundin buyan tarqalmaqta."]],"密西西比":[["密西西比河贯穿美国南部。","مىسسىسىپپى دەرياسى ئامېرىكىنىڭ جەنۇبىنى كېسىپ ئۆتىدۇ.","missisippi deryasi amérikining jenubini késip ötidu."]],"富顺":[["富顺县以出产优质大米而著称。","فۇشۇن ناھىيىسى يۇقىرى سۈپەتلىك گۈرۈچ ئىشلەپچىقىرىش بىلەن داڭلىق.","fushun nahiyisi yuqiri süpetlik gürüch ishlepchiqirish bilen dangliq."]],"宁夏":[["宁夏的羊肉非常美味。","نىڭشيانىڭ قوي گۆشى ئىنتايىن لەززەتلىك.","ningshyaning qoy göshi intayin lezzetlik."]],"宽城县":[["宽城县历史悠久，文化丰富。","كۇەنچېڭ ناھىيەسىنىڭ تارىخى ئۇزۇن، مەدەنىيىتى باي.","kuenchéng nahiyesining tarixi uzun, medeniyiti bay."]],"宝安区":[["宝安区发展迅速。","باۋئەن رايونى تېز تەرەققىي قىلماقتا.","baw'en rayoni téz tereqqiy qilmaqta."]],"寻乌县":[["寻乌县位于江西省南部，历史悠久。","شۈنۋۇ ناھىيىسى جياڭشى ئۆلكىسىنىڭ جەنۇبىدا جايلاشقان بولۇپ، تارىخى ئۇزۇن.","shünwu nahiyisi jyangshi ölkisining jenubida jaylashqan bolup, tarixi uzun."]],"对过":[["他曾经对过那部电影。","ئۇ ئىلگىرى ئۇ كىنونى كۆرگەن.","u ilgiri u kinoni körgen."]],"小儿麻痹":[["小儿麻痹是一种传染病。","كىچىك بالىلار شاللىقى بىر خىل يۇقۇملۇق كېسەللىك.","kichik balilar shalliqi bir xil yuqumluq késellik."]],"射频调谐器":[["射频调谐器可以调节不同频率的频道。","رادىئو چاستوتا تەڭشىگۈچى ئوخشىمىغان چاستوتىدىكى كاناللارنى تەڭشىيەلەيدۇ.","radio chastota tengshigüchi oxshimighan chastotidiki kanallarni tengshiyeleydu."]],"将今论古":[["将今论古能帮助我们理解历史规律。","بۈگۈننى ئەتكەن ئارقىلىق ئۆتكەننى مۇھاكىمە قىلىش تارىخىي قانۇنىيەتلەرنى چۈشىنىشىمىزگە ياردەم بېرىدۇ.","bügünni etken arqiliq ötkenni muhakime qilish tarixiy qanuniyetlerni chüshinishimizge yardem béridu."]],"小打小闹":[["他们只是在小打小闹，并无真正冲突。","ئۇلار پەقەت كىچىك ئۇرۇشۇپ ئوينىشىۋاتىدۇ، ئەمەلىي توقۇنۇش يوق.","ular peqet kichik urushup oynishiwatidu, emeliy toqunush yoq."]],"小川":[["小川清澈见底。","كىچىك ئېقىن تۇپتۇز.","kichik éqin tuptuz."]],"小电驴":[["他骑着小电驴去上班。","ئۇ كىچىك ئېلېكتروسكوپېرىدا ئىشخانىغا باردى.","u kichik éléktroskopérida ishxanigha bardi."]],"小贝":[["小贝是个聪明的小孩。","كىچىك بېي ئەقىللىق بالىدۇر.","kichik béy eqilliq balidur."]],"小货车":[["小货车停在路边。","كىچىك يۈك ماشىنىسى يول بويىدا توختىغان.","kichik yük mashinisi yol boyida toxtighan."]],"就便":[["就便处理一下文件。","ھۆججەتلەرنى شۇ يەردە بىر تەرەپ قىلىۋېلىڭ.","höjjetlerni shu yerde bir terep qiliwéling."]],"尺骨":[["尺骨是前臂的重要骨骼。","ئۆلچەم سۆڭىكى بىلەكنىڭ مۇھىم سۆڭىكىدۇر.","ölchem söngiki bilekning muhim söngikidur."]],"小䴙䴘":[["小䴙䴘在河面上快速游动。","كىچىك سۇغۇرچىقى دەريا يۈزىدە تېز ئۈزىدۇ.","kichik sughurchiqi derya yüzide téz üzidu."]],"少女峰":[["少女峰是阿尔卑斯山的著名山峰。","قىزلار چوققىسى ئالپ تاغلىرىنىڭ مەشھۇر چوققىسى.","qizlar choqqisi alp taghlirining meshhur choqqisi."]],"少安毋躁":[["做事要少安毋躁。","ئىش قىلغاندا ئالدىراپ كەتكۈنچە تىنىچ بولغان ياخشى.","ish qilghanda aldirap ketkünche tinich bolghan yaxshi."]],"尿嘧啶":[["尿嘧啶是核酸的一种碱基。","ئۇراسىل نۇكلېئىن كىسلاتاسىنىڭ بىر خىل ئاساسىدۇر.","urasil nukléin kislatasining bir xil asasidur."]],"尸体解剖":[["尸体解剖是法医的重要工作。","جەسەت يېرىش پاتولوگنىڭ مۇھىم خىزمىتىدۇر.","jeset yérish patologning muhim xizmitidur."]],"屏保":[["他设置了动态的屏保图案。","ئۇ ھەرىكەتچان ئېكران قوغدىغۇچى نەقىشىنى تەڭشىدى.","u heriketchan ékran qoghdighuchi neqishini tengshidi."]],"山阿":[["山阿是幽静的隐居之地。","تاغ قۇچىقى جىمجىت يېتەكچىلىك قىلىدىغان جاي.","tagh quchiqi jimjit yétekchilik qilidighan jay."]],"屠城":[["敌军屠城，血流成河。","دۈشمەن قوشۇنى شەھەرنى قىرغىن قىلىپ، قان دەريا بولۇپ ئاقتى.","düshmen qoshuni sheherni qirghin qilip, qan derya bolup aqti."]],"峨嵋山":[["峨嵋山风景壮丽。","ئېمېي تېغىنىڭ مەنزىرىسى ھەيۋەتلىك.","éméy téghining menzirisi heywetlik."]],"崆峒区":[["崆峒区是兰州市的辖区。","كوڭتۇڭ رايونى لەنجۇ شەھىرىنىڭ باشقۇرۇش رايونى.","kongtung rayoni lenju shehirining bashqurush rayoni."]],"嵊州市":[["嵊州市是浙江省的一个历史文化名城。","شېڭجۇ شەھىرى جېجياڭ ئۆلكىىسىدىكى بىر تارىخىي-مەدەنىي مەشھۇر شەھەر.","shéngju shehiri jéjyang ölkiisidiki bir tarixiy-medeniy meshhur sheher."]],"岚皋县":[["岚皋县地处陕西南部。","لەنگاۋ ناھىيىسى شەنشىنىڭ جەنۇبىدا جايلاشقان.","lengaw nahiyisi shenshining jenubida jaylashqan."]],"州界":[["州界指的是两个州之间的边界。","جوۋجېي ئىككى جوۋ ئارىسىدىكى چېگرانى كۆرسىتىدۇ.","jowjéy ikki jow arisidiki chégrani körsitidu."]],"左联":[["左联是文学团体。","سول بىرلەشمە ئەدەبىيات گۇرۇپپىسىدۇر.","sol birleshme edebiyat guruppisidur."]],"工程图学":[["工程图学教授如何绘制标准技术图纸。","ئىنژېنېرلىق سىزمىشۇناسلىقى ئۆلچەملىك تېخنىكىلىق سىزمىلارنى قانداق سىزىشنى ئۆگىتىدۇ.","inzhénérliq sizmishunasliqi ölchemlik téxnikiliq sizmilarni qandaq sizishni ögitidu."]],"巧妇难为无米之炊":[["巧妇难为无米之炊，食材很重要。","ماھىر ئايال گۈرۈچسىز تائام تەييارلىيالمايدۇ، ئوزۇقلۇق ماددىلىرى ئىنتايىن مۇھىم.","mahir ayal gürüchsiz taam teyyarliyalmaydu, ozuqluq maddiliri intayin muhim."]],"布拉柴维尔":[["布拉柴维尔是刚果共和国的首都。","براززاۋىل كونگو جۇمھۇرىيىتىنىڭ پايتەختى.","brazzawil kongo jumhuriyitining paytexti."]],"市议会":[["市议会批准了新的预算方案。","شەھەرلىك كېڭەش يېڭى بۇدجېت پىلانىنى تەستىقلىدى.","sheherlik kéngesh yéngi budjét pilanini testiqlidi."]],"布莱尼":[["布莱尼的歌声充满力量。","بىرىتنىڭ ناخشا ئاۋازى كۈچكە تولغان.","biritning naxsha awazi küchke tolghan."]],"巴吞鲁日":[["巴吞鲁日是美国路易斯安那州的首府。","باتون رۇژ ئامېرىكىنىڭ لۇئىزانا شىتاتىنىڭ مەركىزى.","baton ruzh amérikining luizana shitatining merkizi."]],"常务理事":[["常务理事定期召开会议讨论事务。","دائىمىي مۇدىرلار قەرەللىك يىغىن ئېچىپ ئىشلارنى مۇزاكىرە قىلىدۇ.","daimiy mudirlar qerellik yighin échip ishlarni muzakire qilidu."]],"带气":[["他说话带气。","ئۇ سۆزلىگەندە ئاچچىقلىنىپ سۆزلەيدۇ.","u sözligende achchiqlinip sözleydu."]],"平鲁":[["平鲁区是山西省的一个行政区。","پىڭلۇ رايونى شەنشى ئۆلكىسىنىڭ بىر مەمۇرىي رايونى.","pinglu rayoni shenshi ölkisining bir memuriy rayoni."]],"平江区":[["平江区是商业繁华的区域。","پىڭجياڭ رايونى سودا گۈللەنگەن رايون.","pingjyang rayoni soda güllengen rayon."]],"平板支撑":[["平板支撑是一种增强核心肌群的常见锻炼。","تەكشى تاختىلىق تىرەك ئاساسىي مۇسكۇل گۇرۇپپىسىنى كۈچەيتىشنىڭ ئادەتتىكى بىر مەشىقى.","tekshi taxtiliq tirek asasiy muskul guruppisini kücheytishning adettiki bir meshiqi."]],"平埔族":[["平埔族是台湾的原住民族群。","پىڭپۇزۇ تەيۋەننىڭ يەرلىك ئاھالىلەر قەۋمى.","pingpuzu teywenning yerlik ahaliler qewmi."]],"师奶":[["师奶是年轻女性的称呼。","شىنەي ياش ئاياللارنىڭ ئاتىلىشىدۇر.","shiney yash ayallarning atilishidur."]],"幸灾乐祸":[["他幸灾乐祸的样子让人讨厌。","ئۇنىڭ باشقىلارنىڭ بەختسىزلىكىدىن خۇشال بولۇش ھالىتى كىشىنى بىزار قىلىدۇ.","uning bashqilarning bextsizlikidin xushal bolush haliti kishini bizar qilidu."]],"干渠":[["干渠将水源输送到各个村庄。","باش ئېرىق سۇ مەنبەسىنى ھەر بىر كەنتكە يەتكۈزىدۇ.","bash ériq su menbesini her bir kentke yetküzidu."]],"庚午":[["庚午年是中国传统干支纪年法。","گېڭۋۇ يىلى جۇڭگونىڭ ئەنئەنىۋى ئاسمان-يەر تەقۋىمىدۇر.","géngwu yili junggoning en'eniwi asman-yer teqwimidur."]],"府上":[["府上指的是贵府或尊贵的住所。","پۇشاڭ سىزنىڭ ئۆيىڭىز ياكى ھۆرمەتلىك تۇرار جايىڭىزنى كۆرسىتىدۇ.","pushang sizning öyingiz yaki hörmetlik turar jayingizni körsitidu."]],"平毁":[["战争导致许多村庄被平毁。","ئۇرۇش نۇرغۇن كەنتلەرنىڭ ۋەيران قىلىنىشىغا سەۋەب بولدى.","urush nurghun kentlerning weyran qilinishigha seweb boldi."]],"平顶山":[["平顶山是中国著名的旅游城市。","تۈزلەڭ تاغ جۇڭگونىڭ داڭلىق ساياھەت شەھىرى.","tüzleng tagh junggoning dangliq sayahet shehiri."]],"弗兰西斯·培根":[["弗兰西斯·培根是英国哲学家。","فرانسىس بېيكون ئەنگلىيەلىك پەلسەپىچى.","fransis béykon engliyelik pelsepichi."]],"弗吉尼亚州":[["弗吉尼亚州以美丽的自然风光闻名。","ۋىرگىنىيە شىتاتى گۈزەل تەبىئىي مەنزىرىسى بىلەن تونۇلغان.","wirginiye shitati güzel tebiiy menzirisi bilen tonulghan."]],"张闻天":[["张闻天是中国共产党早期领导人。","جاڭ ۋېنتيەن جۇڭگو كوممۇنىستىك پارتىيەسىنىڭ دەسلەپكى رەھبەرلىرىدىن بىرى.","jang wéntyen junggo kommunistik partiyesining deslepki rehberliridin biri."]],"张华":[["张华是西晋时期的文学家。","جاڭ خۇا غەربىي جىن سۇلالىسى دەۋرىدىكى ئەدىب.","jang xua gherbiy jin sulalisi dewridiki edib."]],"弹指":[["他弹指间就完成了动作。","ئۇ بارماق شىقىلدىتىش ئارىلىقىدا ھەرىكەتنى تاماملىدى.","u barmaq shiqilditish ariliqida heriketni tamamlidi."]],"弹片":[["弹片可能伤及周围人员。","گىلۇلە پارچىلىرى ئەتراپتىكى كىشىلەرگە زىيان يەتكۈزۈشى مۇمكىن.","gilule parchiliri etraptiki kishilerge ziyan yetküzüshi mumkin."]],"弹球盘":[["弹球盘里装满了彩色弹珠。","شار ئويۇن تاختىسى رەڭلىك شارلار بىلەن تولغان.","shar oyun taxtisi renglik sharlar bilen tolghan."]],"彼尔姆":[["彼尔姆是俄罗斯的一座城市。","پېرم رۇسىيەنىڭ بىر شەھىرى.","pérm rusiyening bir shehiri."]],"影儿":[["影儿在舞台上表演。","سايە سەھنىدە ئويۇن كۆرسەتتى.","saye sehnide oyun körsetti."]],"彩卷":[["彩卷的开奖结果令人惊喜。","رەڭدار بېلەتنىڭ ئېچىلىش نەتىجىسى كىشىنى ھەيران قالدۇردى.","rengdar béletning échilish netijisi kishini heyran qaldurdi."]],"从一而终":[["她对爱情始终从一而终，从未变心。","ئۇ مۇھەببەتكە ئاخىرغىچە سادىق بولدى، ھەرگىز كۆڭلىنى ئۆزگەرتمىدى.","u muhebbetke axirghiche sadiq boldi, hergiz könglini özgertmidi."]],"忍痛":[["他忍痛完成了任务。","ئۇ ئاغرىققا چىداپ ۋەزىپىنى ئورۇندىدى.","u aghriqqa chidap wezipini orundidi."]],"快马加鞭":[["他快马加鞭，终于在截止日期前完成。","ئۇ ئاتنى قاملاققا مىندى ۋە ئاخىرى مۇددەتتىن بۇرۇن تاماملىدى.","u atni qamlaqqa mindi we axiri muddettin burun tamamlidi."]],"快点":[["请快点，我们快要迟到了！","تېزرەك بولۇڭ، بىز ئاز قالغاندا كېچىكىپ قالىمىز!","tézrek bolung, biz az qalghanda kéchikip qalimiz!"]],"性侵":[["他遭遇了性侵。","ئۇ جىنسىي زوراۋانلىققا ئۇچرىدى.","u jinsiy zorawanliqqa uchridi."]],"性服务产业":[["性服务产业在全球范围内持续扩张。","جىنسىي مۇلازىمەت كەسپى دۇنيا مىقياسىدا داۋاملىق كېڭەيمەكتە.","jinsiy mulazimet kespi dunya miqyasida dawamliq kéngeymekte."]],"性疾病":[["这种性疾病可以通过疫苗预防。","بۇ خىل كېسەللىكنى ۋاكسىنا ئارقىلىق ئالدىنى ئېلىشقا بولىدۇ.","bu xil késellikni waksina arqiliq aldini élishqa bolidu."]],"恩德":[["他的恩德深厚，令人感激不尽。","ئۇنىڭ مەرھەمىتى چوڭقۇر بولۇپ، كىشىنى چەكسىز مىننەتدار قىلىدۇ.","uning merhemiti chongqur bolup, kishini cheksiz minnetdar qilidu."]],"心理词典":[["这本心理词典收录了专业术语和解释。","بۇ پسىخولوگىيەلىك لۇغەت كەسپىي ئاتالغۇلار ۋە چۈشەندۈرۈشلەرنى ئۆز ئىچىگە ئالىدۇ.","bu psixologiyelik lughet kespiy atalghular we chüshendürüshlerni öz ichige alidu."]],"心疑":[["心疑的种子一旦发芽，便会滋生不安。","شۈبھىلەنش قۇرۇقى بىر قېتىم كۆكلىسە، بىئاراملىقنى يېتىلدۈرىدۇ.","shübhilensh quruqi bir qétim köklise, biaramliqni yétildüridu."]],"心眼大":[["心眼大的人更容易包容他人的过错。","كۆڭلى كەڭ كىشىلەر باشقىلارنىڭ خاتالىقىنى ئاسان كەچۈرۈم قىلىدۇ.","köngli keng kishiler bashqilarning xataliqini asan kechürüm qilidu."]],"悉德尼":[["悉德尼是悉尼的别称。","سىدنىي سىدنېينىڭ باشقا ئاتىلىشى.","sidniy sidnéyning bashqa atilishi."]],"愚不可及":[["他的愚蠢愚不可及。","ئۇنىڭ ئەخمىقلىقى چەكسىز ئەخمىقلىق.","uning exmiqliqi cheksiz exmiqliq."]],"惑星":[["这颗惑星在夜空中格外明亮。","بۇ سەييارە كېچە ئاسمىنىدا ئالاھىدە پارلاپ تۇراتتى.","bu seyyare kéche asminida alahide parlap turatti."]],"惠城":[["惠城是惠州市的中心城区。","خۇيچېڭ خۇيجۇ شەھىرىنىڭ مەركىزىي شەھەر رايونى.","xuychéng xuyju shehirining merkiziy sheher rayoni."]],"爱德华王子岛":[["爱德华王子岛以海鲜闻名。","ئېدۋارد شاھزادە ئارىلى دېڭىز مەھسۇلاتلىرى بىلەن داڭلىق.","édward shahzade arili déngiz mehsulatliri bilen dangliq."]],"想要":[["我想要一个礼物。","مەن بىر سوۋغات ئالماقچى.","men bir sowghat almaqchi."]],"应用层":[["应用层负责数据传输。","ئەپلىكەش قەۋىتى سانلىق مەلۇمات يەتكۈزۈشكە مەسئۇل.","eplikesh qewiti sanliq melumat yetküzüshke mes'ul."]],"悬崖绝壁":[["悬崖绝壁高耸入云，令人望而生畏。","تىك يارنىڭ قىيالىقى بۇلۇتلارغا تەڭ كۆتۈرۈلۈپ، كىشىنى ھەيۋەتكە سالىدۇ.","tik yarning qiyaliqi bulutlargha teng kötürülüp, kishini heywetke salidu."]],"戒刀":[["古代的刽子手使用戒刀执行死刑。","قەدىمكى زاماندا جازالاش ئىجرا قىلغۇچىلار ئۆلۈم جازاسىنى ئىجرا قىلىش ئۈچۈن جازا پىچىقىنى ئىشلەتكەن.","qedimki zamanda jazalash ijra qilghuchilar ölüm jazasini ijra qilish üchün jaza pichiqini ishletken."]],"户内":[["户内设施需要定期检查。","ئۆي ئىچى ئەسلىھەلىرىنى مۇنتىزىم تەكشۈرتۈش كېرەك.","öy ichi eslihelirini muntizim tekshürtüsh kérek."]],"扒开":[["他扒开人群，挤到前面去。","ئۇ ئادەملەرنى يېرىپ، ئالدى تەرەپكە سۈرۈلۈپ كەتتى.","u ademlerni yérip, aldi terepke sürülüp ketti."]],"打蜡":[["家具打蜡能让表面更光滑。","ئۆي جاھازىلىرىغا موم سۈركەش يۈزىنى تېخىمۇ سىلىق قىلىدۇ.","öy jahazilirigha mom sürkesh yüzini téximu siliq qilidu."]],"成不了气候":[["这个计划根本成不了气候。","بۇ پىلان ئاساسەن ھېچقانداق نەتىجە قازىنالمايدۇ.","bu pilan asasen héchqandaq netije qazinalmaydu."]],"承重":[["这座桥梁的承重能力很强。","بۇ كۆۋرۈكنىڭ يۈك كۆتۈرۈش قابىلىيىتى ناھايىتى كۈچلۈك.","bu köwrükning yük kötürüsh qabiliyiti nahayiti küchlük."]],"抗议者":[["抗议者聚集在政府大楼前。","نارازىلىق بىلدۈرگۈچىلەر ھۆكۈمەت بىناسىنىڭ ئالدىغا جەم بولدى.","naraziliq bildürgüchiler hökümet binasining aldigha jem boldi."]],"找茬":[["他故意找茬，想挑起冲突。","ئۇ قەستەن سەۋەنلىك تېپىپ، توقۇنۇش قوزغىماقچى بولدى.","u qesten sewenlik tépip, toqunush qozghimaqchi boldi."]],"承籍":[["他承籍于当地的户籍系统。","ئۇ يەرلىك نوپۇس سىستېمىسىغا تىزىملانغان.","u yerlik nopus sistémisigha tizimlanghan."]],"拉丁字母":[["拉丁字母广泛用于欧洲。","لاتىن ھەرپلىرى ياۋروپادا كەڭ قوللىنىلىدۇ.","latin herpliri yawropada keng qollinilidu."]],"抗日":[["全国人民团结抗日，共赴国难。","پۈتۈن مەملىكەت خەلقى بىرلىكتە ياپونىيە باسقۇنچىلىرىغا قارشى تۇرۇپ، دۆلەت ئاپىتىگە بىرلىكتە بارىدۇ.","pütün memliket xelqi birlikte yaponiye basqunchilirigha qarshi turup, dölet apitige birlikte baridu."]],"扎眼":[["这个颜色特别扎眼。","بۇ رەڭ ئىنتايىن كۆزگە چېلىقىدۇ.","bu reng intayin közge chéliqidu."]],"批假":[["他向领导申请批假两天。","ئۇ رەھبەردىن ئىككى كۈنلۈك رۇخسەت سورىدى.","u rehberdin ikki künlük ruxset soridi."]],"批汇":[["公司负责处理国际批汇业务。","شىركەت خەلقئارا پۇل ئالماشتۇرۇش ئىشلىرىنى بىر تەرەپ قىلىشقا مەسئۇل.","shirket xelq'ara pul almashturush ishlirini bir terep qilishqa mes'ul."]],"批文":[["批文是办理手续的重要依据。","تەستىق ھۆججىتى رەسمىيەت بىجىرىشتە مۇھىم ئاساسدۇر.","testiq höjjiti resmiyet bijirishte muhim asasdur."]],"拉斯穆森":[["拉斯穆森是丹麦政治家。","راسمۇسسېن دانىيە سىياسەتچىسى.","rasmussén daniye siyasetchisi."]],"抓紧学习":[["要抓紧学习。","ئۆگىنىشنى چىڭ تۇتۇش كېرەك.","öginishni ching tutush kérek."]],"投影仪":[["投影仪连接电脑后开始播放。","پرويېكتور كومپيۇتېرغا ئۇلانغاندىن كېيىن قويۇشقا باشلايدۇ.","proyéktor kompyutérgha ulanghandin kéyin qoyushqa bashlaydu."]],"指法":[["指法直接影响钢琴演奏的效果。","بارماق ئۇسۇلى پىيانىنو چېلىش ئۈنۈمىگە بىۋاسىتە تەسىر كۆرسىتىدۇ.","barmaq usuli piyanino chélish ünümige biwasite tesir körsitidu."]],"捐益表":[["他提交了捐益表。","ئۇ ئىئانە-پايدا جەدۋىلىنى تاپشۇردى.","u iane-payda jedwilini tapshurdi."]],"捐精":[["他参与了捐精活动。","ئۇ ئۇرۇق ھەدىيە قىلىش پائالىيىتىگە قاتناشتى.","u uruq hediye qilish paaliyitige qatnashti."]],"排检":[["医生进行排检诊断。","دوختۇر تەكشۈرۈش دىئاگنوزى ئېلىپ باردى.","doxtur tekshürüsh diagnozi élip bardi."]],"掉书袋":[["他总爱掉书袋，让人很烦。","ئۇ ھەمىشە كىتاب سۆزلىرىنى ئىشلىتىپ كىشىلەرنى زېرىكتۈرىدۇ.","u hemishe kitab sözlirini ishlitip kishilerni zériktüridu."]],"授时":[["天文台负责授时服务。","ئاسترونومىيە رەسەتخانىسى ۋاقىت بېرىش مۇلازىمىتىگە مەسئۇل.","astronomiye resetxanisi waqit bérish mulazimitige mes'ul."]],"探子":[["探子负责传递情报信息。","جاسۇس ئۇچۇر يەتكۈزۈشكە مەسئۇل.","jasus uchur yetküzüshke mes'ul."]],"提款":[["他通过提款取出了部分现金。","ئۇ پۇل ئېلىش ئارقىلىق بىر قىسىم نەق پۇل ئالدى.","u pul élish arqiliq bir qisim neq pul aldi."]],"搜神记":[["阅读《搜神记》故事。","«ئىزدەش ئىلاھىسى» ھېكايىسىنى ئوقۇڭ.","«izdesh ilahisi» hékayisini oqung."]],"挑食":[["孩子挑食，只吃自己喜欢的菜。","بالا تاماق تاللايدۇ، پەقەت ئۆزى ياخشى كۆرىدىغان تاماقنىلا يەيدۇ.","bala tamaq tallaydu, peqet özi yaxshi köridighan tamaqnila yeydu."]],"掬诚":[["他掬诚待人，赢得了大家的信任。","ئۇ سەمىمىيەت بىلەن كىشىلەرگە مۇئامىلە قىلىپ، كۆپچىلىكنىڭ ئىشەنچىسىگە ئېرىشتى.","u semimiyet bilen kishilerge muamile qilip, köpchilikning ishenchisige érishti."]],"抟饭":[["她正在用勺子抟饭盛入碗中。","ئۇ قوشۇق بىلەن تاماقنى ئېزىپ چىنەگە سېلىۋاتىدۇ.","u qoshuq bilen tamaqni ézip chinege séliwatidu."]],"掸邦":[["掸邦是缅甸的一个地区。","شان ئوبلاستى بىرما رايونىدىكى بىر رايون.","shan oblasti birma rayonidiki bir rayon."]],"撂地":[["演员在撂地表演时吸引了观众。","ئارتىس ئوچۇق مەيداندا ئويۇن كۆرسىتىپ، تاماشىبىنلارنى جەلپ قىلدى.","artis ochuq meydanda oyun körsitip, tamashibinlarni jelp qildi."]],"击沉":[["军舰被鱼雷击沉了。","ھەربىي كېمە تورپېدا بىلەن چۆكتۈرۈلدى.","herbiy kéme torpéda bilen chöktürüldi."]],"撒切尔夫人":[["撒切尔夫人以铁腕政策闻名。","تاتچېر خانىم تۆمۈر مۇشت سىياسىتى بىلەن تونۇلغان.","tatchér xanim tömür musht siyasiti bilen tonulghan."]],"搞不好":[["搞不好会出问题的。","بەلكىم مەسىلە كېلىپ چىقىشى مۇمكىن.","belkim mesile kélip chiqishi mumkin."]],"搭把手":[["请搭把手搬东西。","ياردەم بېرىپ ئەشيالارنى يۆتكەڭ.","yardem bérip eshyalarni yötkeng."]],"搅打":[["用搅拌机搅打食材。","ئارىلاشتۇرغۇچتا يېمەكلىك ماتېرىياللىرىنى ئارىلاشتۇر.","arilashturghuchta yémeklik matériyallirini arilashtur."]],"改过":[["他改过错误。","ئۇ خاتالىقىنى تۈزەتتى.","u xataliqini tüzetti."]],"故道":[["这条故道曾是古代的重要交通要道。","بۇ كونا يول ئىلگىرى قەدىمكى دەۋردىكى مۇھىم قاتناش يولى ئىدى.","bu kona yol ilgiri qedimki dewrdiki muhim qatnash yoli idi."]],"叙旧":[["我们叙旧聊了许久。","بىز كونا ئەھۋاللارنى سۆزلەپ ئۇزۇن ۋاقىت پاراڭلاشتۇق.","biz kona ehwallarni sözlep uzun waqit paranglashtuq."]],"敌机":[["敌机被防空炮击落。","دۈشمەن ئايروپىلانى ھاۋا مۇداپىئە توپى تەرىپىدىن ئۇرۇپ چۈشۈرۈلدى.","düshmen ayropilani hawa mudapie topi teripidin urup chüshürüldi."]],"数字通信":[["数字通信让信息传递更高效。","رەقەملىك ئالاقە ئۇچۇر يەتكۈزۈشنى تېخىمۇ يۇقىرى ئۈنۈملۈك قىلىدۇ.","reqemlik alaqe uchur yetküzüshni téximu yuqiri ünümlük qilidu."]],"文法":[["文法研究语言的规则与结构。","گرامماتىكا ئىلمى تىلنىڭ قائىدىسى ۋە قۇرۇلمىسىنى تەتقىق قىلىدۇ.","grammatika ilmi tilning qaidisi we qurulmisini tetqiq qilidu."]],"文登市":[["文登市以旅游和农业闻名。","ۋېندېڭ شەھىرى ساياھەت ۋە دېھقانچىلىق بىلەن داڭلىق.","wéndéng shehiri sayahet we déhqanchiliq bilen dangliq."]],"整体数位服务网路":[["整体数位服务网路覆盖广泛。","پۈتۈنلەي گەۋدە سانلىق مەلۇمات مۇلازىمەت تورى كەڭ دائىرىنى قاپلىدى.","pütünley gewde sanliq melumat mulazimet tori keng dairini qaplidi."]],"整体服务数位网路":[["整体服务数位网路效率很高。","پۈتۈنلەي گەۋدە مۇلازىمەت سانلىق مەلۇمات تورىنىڭ ئۈنۈمى ئىنتايىن يۇقىرى.","pütünley gewde mulazimet sanliq melumat torining ünümi intayin yuqiri."]],"斑鹟":[["斑鹟是一种擅长捕食昆虫的鸟类。","داغلىق چىۋىقچى قۇش ھاشارات ئوۋلاشقا ماھىر قۇش تۈرىدۇر.","daghliq chiwiqchi qush hasharat owlashqa mahir qush türidur."]],"斩获":[["部队在战斗中斩获了胜利。","جەڭدە قىسىم غەلىبە قازاندى.","jengde qisim ghelibe qazandi."]],"文化传统":[["春节是中国重要的文化传统。","باھار بايرىمى جۇڭگونىڭ مۇھىم مەدەنىيەت ئەنئەنىسىدۇر.","bahar bayrimi junggoning muhim medeniyet en'enisidur."]],"新郎倌":[["新郎倌在婚礼上笑容满面。","يېڭى كۈيئوغۇل توي مۇراسىمىدا چىرايىدىن كۈلۈپ تۇردى.","yéngi küy'oghul toy murasimida chirayidin külüp turdi."]],"新乡县":[["新乡县的特产很有名。","شىنشياڭ ناھىيىسىنىڭ ئالاھىدە مەھسۇلاتلىرى ئىنتايىن داڭلىق.","shinshyang nahiyisining alahide mehsulatliri intayin dangliq."]],"施事":[["施事是语法中的核心概念。","ئىگە ئەمەل قىلغۇچى گرامماتىكىدىكى يادرولۇق ئۇقۇمدۇر.","ige emel qilghuchi grammatikidiki yadroluq uqumdur."]],"施压":[["政府对污染企业施压。","ھۆكۈمەت بۇلغىنىش كەلتۈرۈپ چىقارغۇچى كارخانىلارغا بېسىم ئىشلەتتى.","hökümet bulghinish keltürüp chiqarghuchi karxanilargha bésim ishletti."]],"旗津":[["旗津是一个美丽的港口。","بايراقجىن گۈزەل بىر پورت.","bayraqjin güzel bir port."]],"旗开得胜":[["比赛一开始，他就旗开得胜。","مۇسابىقە باشلىنىشى بىلەنلا ئۇ بايراق كۆتۈرۈپ غەلىبە قازاندى.","musabiqe bashlinishi bilenla u bayraq kötürüp ghelibe qazandi."]],"早起":[["早起对身体有很多好处。","بالدۇر تۇرۇشنىڭ بەدەنگە نۇرغۇن پايدىسى بار.","baldur turushning bedenge nurghun paydisi bar."]],"易如反掌":[["这件事对他来说易如反掌。","بۇ ئىش ئۇنىڭ ئۈچۈن ئاسان ئىدى.","bu ish uning üchün asan idi."]],"昌都县":[["昌都县位于西藏自治区东部。","چاڭدۇ ناھىيىسى تىبەت ئاپتونوم رايونىنىڭ شەرقىي قىسمىدا جايلاشقان.","changdu nahiyisi tibet aptonom rayonining sherqiy qismida jaylashqan."]],"明晃晃":[["阳光明晃晃地照着。","قۇياش نۇرى پارقىراپ چۈشۈپ تۇرۇپتۇ.","quyash nuri parqirap chüshüp turuptu."]],"春柳":[["春柳随风轻摆，婀娜多姿。","باھار تالىسى شامالدا ئاستا تەۋرىنىپ، نازۇك ھەرىكەتلىنىدۇ.","bahar talisi shamalda asta tewrinip, nazuk heriketlinidu."]],"春凳":[["春凳是传统家具的一种。","باھار ئورۇندۇقى ئەنئەنىۋى ئۆي جاھازىلىرىنىڭ بىر تۈرى.","bahar orunduqi en'eniwi öy jahazilirining bir türi."]],"昴宿星团":[["昴宿星团在夜空中格外醒目。","ئەلچى يۇلتۇزلار توپى كېچە ئاسمانىدا ئالاھىدە كۆزگە چېلىقىدۇ.","elchi yultuzlar topi kéche asmanida alahide közge chéliqidu."]],"晏平仲":[["晏平仲是晏婴的字。","يەنپىڭجۇڭ يەنيىڭنىڭ لەقىمى.","yenpingjung yenyingning leqimi."]],"晚辈":[["晚辈应该尊重长辈的意见。","كىچىكلەر چوڭلارنىڭ پىكرىگە ھۆرمەت قىلىشى كېرەك.","kichikler chonglarning pikrige hörmet qilishi kérek."]],"晦气":[["他今天真是晦气，接连倒霉。","ئۇ بۈگۈن ھەقىقەتەن بەختسىز، ئارقا-ئارقىدىن ئامەتسىزلىككە ئۇچرىدى.","u bügün heqiqeten bextsiz, arqa-arqidin ametsizlikke uchridi."]],"暗冕鹪莺":[["暗冕鹪莺是一种小型的鸣禽。","يوشۇرۇن تاجلىق چىۋىقىن كىچىك سайرايدىغان قۇش.","yoshurun tajliq chiwiqin kichik sайraydighan qush."]],"暗哨儿":[["暗哨儿是隐蔽的监视点。","يوشۇرۇن قاراۋۇلچە مەخپىي نازارەت نۇقتىسى.","yoshurun qarawulche mexpiy nazaret nuqtisi."]],"晶体结构":[["晶体结构影响物质的稳定性。","كرىستال قۇرۇلمىسى ماددىنىڭ مۇقىملىقىغا تەسىر كۆرسىتىدۇ.","kristal qurulmisi maddining muqimliqigha tesir körsitidu."]],"暴风圈":[["台风中心被称为暴风圈。","تايفۇن مەركىزى بوران چەمبىرى دەپ ئاتىلىدۇ.","tayfun merkizi boran chembiri dep atilidu."]],"会合":[["他们在车站成功会合。","ئۇلار بېكەتتە مۇۋەپپەقىيەتلىك ئۇچراشتى.","ular békette muweppeqiyetlik uchrashti."]],"会师":[["两军在此会师，共同作战。","ئىككى ئارمىيە بۇ يەردە بىرلىشىپ، بىرلىكتە جەڭ قىلدى.","ikki armiye bu yerde birliship, birlikte jeng qildi."]],"月光族":[["月光族月底总拮据。","ئاي نۇرى ئائىلىسى ئاي ئاخىرىدا ھەمىشە تارچىلىق تارتىدۇ.","ay nuri ailisi ay axirida hemishe tarchiliq tartidu."]],"曼德拉":[["曼德拉是南非的前总统。","ماندېلا جەنۇبىي ئافرىقىنىڭ سابىق پرېزىدېنتى.","mandéla jenubiy afriqining sabiq prézidénti."]],"有机土":[["有机土适合种植蔬菜。","ئورگانىك تۇپراق كۆكتات ئۆستۈرۈشكە ماس كېلىدۇ.","organik tupraq köktat östürüshke mas kélidu."]],"朝鲜语":[["朝鲜语属于阿尔泰语系。","چاۋشيەن تىلى ئالتاي تىل سىستېمىسىغا تەۋە.","chawshyen tili altay til sistémisigha tewe."]],"期中":[["期中成绩反映了学生前半学期的学习情况。","ئوتتۇرا مۇددەتلىك ئىمتىھان نەتىجىسى ئوقۇغۇچىلارنىڭ ئالدىنقى يېرىم مەۋسۇمدىكى ئۆگىنىش ئەھۋالىنى ئەكس ئەتتۈرىدۇ.","ottura muddetlik imtihan netijisi oqughuchilarning aldinqi yérim mewsumdiki öginish ehwalini eks ettüridu."]],"有罪不罚":[["有罪不罚的现象令人担忧。","گۇناھنىڭ جازاسىز قېلىش ھادىسىسى كىشىنى ئەندىشىگە سالىدۇ.","gunahning jazasiz qélish hadisisi kishini endishige salidu."]],"木糖":[["这种木糖常用于食品工业。","بۇ خىل ياغاچ شېكىرى كۆپىنچە يېمەكلىك سانائىتىدە ئىشلىتىلىدۇ.","bu xil yaghach shékiri köpinche yémeklik sanaitide ishlitilidu."]],"札达县":[["札达县拥有丰富的历史文化资源。","زادا ناھىيىسى مول تارىخىي-مەدەنىيەت بايلىقلىرىغا ئىگە.","zada nahiyisi mol tarixiy-medeniyet bayliqlirigha ige."]],"朱丽亚":[["朱丽亚是歌剧中的经典角色。","جۇلىيا ئوپېرادىكى كلاسسىك رول.","juliya opéradiki klassik rol."]],"杜松子":[["杜松子常被用来制作果酒。","دۇجۇڭزى ئادەتتە مېۋە شارابى ياساشقا ئىشلىتىلىدۇ.","dujungzi adette méwe sharabi yasashqa ishlitilidu."]],"东床":[["他成了东床快婿，备受宠爱。","ئۇ دۇڭچۇاڭنىڭ ئەڭ ياخشى كۈيئوغۇلى بولۇپ، ئىنتايىن ئېرىشكەن.","u dungchuangning eng yaxshi küy'oghuli bolup, intayin érishken."]],"东征西怨":[["东征西怨，形容四处征战。","شەرققە يۈرۈش قىلسا غەرب ئاغرىنىدۇ، دېگەن سۆز تۆت تەرەپكە جەڭ قىلىشنى تەسۋىرلەيدۇ.","sherqqe yürüsh qilsa gherb aghrinidu, dégen söz töt terepke jeng qilishni teswirleydu."]],"东征西讨":[["东征西讨，形容四处征伐。","شەرققە يۈرۈش قىلىپ غەربنى تىزگىنلەش، تۆت تەرەپكە جەڭ قىلىشنى تەسۋىرلەيدۇ.","sherqqe yürüsh qilip gherbni tizginlesh, töt terepke jeng qilishni teswirleydu."]],"东台市":[["东台市以优质的农产品闻名。","دۇڭتەي شەھىرى سۈپەتلىك يېزا ئىگىلىك مەھسۇلاتلىرى بىلەن ئاتاقلىق.","dungtey shehiri süpetlik yéza igilik mehsulatliri bilen ataqliq."]],"东条英机":[["东条英机是二战时期的日本首相。","دۇڭتياۋ يىنگىجى ئىككىنچى دۇنيا ئۇرۇشى مەزگىلىدىكى ياپونىيە باش ۋەزىرى.","dungtyaw yingiji ikkinchi dunya urushi mezgilidiki yaponiye bash weziri."]],"枕石漱流":[["他喜欢枕石漱流的生活。","ئۇ ياستۇق تاشقا باش قويۇپ، ئېقىن سۇدا چايقىلىپ ياشاشنى ياخشى كۆرىدۇ.","u yastuq tashqa bash qoyup, éqin suda chayqilip yashashni yaxshi köridu."]],"林则徐":[["林则徐是中国历史上的著名人物。","لىن زېشۈ جۇڭگو تارىخىدىكى مەشھۇر شەخس.","lin zéshü junggo tarixidiki meshhur shexs."]],"林周县":[["林周县以独特的自然风光著称。","لىنجو ناھىيىسى ئۆزگىچە تەبىئىي مەنزىرىسى بىلەن تونۇلغان.","linjo nahiyisi özgiche tebiiy menzirisi bilen tonulghan."]],"板门店":[["板门店是朝韩的分界线。","تاختا دۇكانى شىمالىي كورېيە بىلەن جەنۇبىي كورېيەنىڭ ئايرىش سىزىقى.","taxta dukani shimaliy koréye bilen jenubiy koréyening ayrish siziqi."]],"松本":[["松本是日本著名的音乐家。","سۇڭبېن ياپونىيەنىڭ مەشھۇر مۇزىكانتى.","sungbén yaponiyening meshhur muzikanti."]],"松雀鹰":[["松雀鹰是一种以小型鸟类为食的猛禽。","سۇڭچۆيىڭ كىچىك قۇشلار بىلەن ئوزۇقلىنىدىغان يىرتقۇچ قۇش.","sungchöying kichik qushlar bilen ozuqlinidighan yirtquch qush."]],"枯朽":[["这座古桥因长期风吹雨打而变得枯朽。","بۇ قەدىمىي كۆۋرۈك ئۇزۇن مۇددەت شامال-يامغۇرغا ئۇچرىغاچقا قۇرۇپ ھاراپ بولغان.","bu qedimiy köwrük uzun muddet shamal-yamghurgha uchrighachqa qurup harap bolghan."]],"杉林":[["这片杉林景色优美。","بۇ سۇگى ئورمانلىقىنىڭ مەنزىرىسى گۈزەل.","bu sugi ormanliqining menzirisi güzel."]],"柘浆":[["柘浆是柘树提取的汁液。","جې شەربىتى جې دەرىخىدىن ئېلىنغان شىرنە.","jé sherbiti jé derixidin élinghan shirne."]],"柳丁":[["柳丁是水果的一种，富含维生素。","ئاپېلسىن مېۋىنىڭ بىر تۈرى بولۇپ، ۋىتامىنغا باي.","apélsin méwining bir türi bolup, witamingha bay."]],"核燃料":[["核燃料是反应堆的能量来源。","يادرو يېقىلغۇسى رېئاكتورنىڭ ئېنېرگىيە مەنبەسىدۇر.","yadro yéqilghusi réaktorning énérgiye menbesidur."]],"柳毅传":[["《柳毅传》是中国古代的一篇传奇故事，广为流传。","«ليۇيى جىڭى» جۇڭگونىڭ قەدىمكى زامانىدىكى بىر رىۋايەت ھېكايىسى بولۇپ، كەڭ تارقالغان.","«lyuyi jingi» junggoning qedimki zamanidiki bir riwayet hékayisi bolup, keng tarqalghan."]],"桂阳县":[["桂阳县位于湖南省境内。","گۈيياڭ ناھىيىسى خۇنەن ئۆلكىسىنىڭ تەۋەسىدە.","güyyang nahiyisi xunen ölkisining teweside."]],"核武":[["核武是战略威慑的重要工具。","يادرو قورالى ئىستراتېگىيەلىك تەھدىت قىلىشنىڭ مۇھىم قورالى.","yadro qorali istratégiyelik tehdit qilishning muhim qorali."]],"格子棉布":[["格子棉布常用于制作服装。","كاتەك پاختا رەخت كۆپىنچە كىيىم تىكىشتە ئىشلىتىلىدۇ.","katek paxta rext köpinche kiyim tikishte ishlitilidu."]],"梅里雪山":[["梅里雪山是云南的著名旅游景点。","Meili قار تېغى bolsa Yünnénنىڭ داڭلىق ساياھەت مەنزىلى.","Meili qar téghi bolsa Yünnénning dangliq sayahet menzili."]],"梵克雅宝":[["她戴着梵克雅宝的项链。","ئۇ ۋانكلىف ئارپا تىزمىسىنى تاقىۋالغان.","u wanklif arpa tizmisini taqiwalghan."]],"棺木":[["古代棺木多用珍贵木材制成。","قەدىمكى زاماندا تابۇت كۆپىنچە قىممەتلىك ياغاچتىن ياسالغان.","qedimki zamanda tabut köpinche qimmetlik yaghachtin yasalghan."]],"椆水":[["椆水是一种清澈的泉水。","چيۇشۇي بىر خىل سۈزۈك بۇلاق سۈيى.","chyushuy bir xil süzük bulaq süyi."]],"栈架":[["栈架用来支撑棚顶的结构。","زاڭ رامكا كەپە تۆمۈرىنىڭ قۇرۇلمىسىنى قوللاپ تۇرىدۇ.","zang ramka kepe tömürining qurulmisini qollap turidu."]],"栈顶":[["栈顶可以欣赏到壮丽景色。","زاڭ چوققىسىدىن ھەيۋەتلىك مەنزىرىنى تاماشا قىلغىلى بولىدۇ.","zang choqqisidin heywetlik menzirini tamasha qilghili bolidu."]],"极小":[["这个函数的极小值接近于零。","بۇ فۇنكسىيەنىڭ ئەڭ كىچىك قىممىتى نۆلگە يېقىن.","bu funksiyening eng kichik qimmiti nölge yéqin."]],"榨取":[["公司被指责过度榨取员工。","شىركەت خىزمەتچىلەرنى ھەددىدىن زىيادە سىقىپ ئىشلىتىۋاتىدۇ دەپ ئەيىبلەندى.","shirket xizmetchilerni heddidin ziyade siqip ishlitiwatidu dep eyiblendi."]],"条贯":[["古代朝廷的条贯非常严格。","قەدىمكى زاماندىكى ھۆكۈمەتنىڭ تۈزۈملىرى ئىنتايىن قاتتىق ئىدى.","qedimki zamandiki hökümetning tüzümliri intayin qattiq idi."]],"荣辱":[["他面对荣辱始终泰然自若。","ئۇ شەرەپ ۋە شەرمەندىلىككە دۇچ كەلگەندە ھەمىشە تىنچ ۋە بىخەتەر بولدى.","u sherep we shermendilikke duch kelgende hemishe tinch we bixeter boldi."]],"概数":[["这个概数接近实际数值。","بۇ تەخمىنىي سان ئەمەلىي قىممەتكە يېقىن.","bu texminiy san emeliy qimmetke yéqin."]],"概述":[["会议最后对成果进行了概述。","يىغىن ئاخىرىدا نەتىجىلەرگە ئومۇمىي بايان بەردى.","yighin axirida netijilerge omumiy bayan berdi."]],"桦南县":[["桦南县位于黑龙江省。","خۇانەن ناھىيىسى خېيلۇڭجياڭ ئۆلكىسىدە جايلاشقان.","xuanen nahiyisi xéylungjyang ölkiside jaylashqan."]],"机务段":[["机务段负责列车的维护工作。","ماشىنا ئىشلىرى بۆلۈمى پويىزلارنى ئاسراش خىزمىتىگە مەسئۇل.","mashina ishliri bölümi poyizlarni asrash xizmitige mes'ul."]],"枪战":[["激烈的枪战持续了数小时。","شىددەتلىك ئوق ئېتىش جېڭى بىر نەچچە سائەت داۋاملاشتى.","shiddetlik oq étish jéngi bir nechche saet dawamlashti."]],"枪托":[["枪托是支撑手臂的重要部件。","ئوق قوندىقى قولنى تىرەيدىغان مۇھىم قىسىم.","oq qondiqi qolni tireydighan muhim qisim."]],"机票":[["他预订了飞往东京的机票。","ئۇ توكيوغا ئۇچىدىغان ئايروپىلان بېلىتىنى بۇيرۇتتى.","u tokyogha uchidighan ayropilan bélitini buyrutti."]],"横七竖八":[["房间里的东西横七竖八。","ئۆيدىكى نەرسىلەر قالايمىقان تاشلانغان.","öydiki nersiler qalaymiqan tashlanghan."]],"档案分配区":[["档案分配区用于分类存储文件。","ھۆججەت تەقسىملەش رايونى ھۆججەتلەرنى تۈرگە ئايرىپ ساقلاشقا ئىشلىتىلىدۇ.","höjjet teqsimlesh rayoni höjjetlerni türge ayrip saqlashqa ishlitilidu."]],"武士道":[["武士道强调忠诚与荣誉。","ۋۇشىدائو سادىقلىق ۋە شەرەپنى تەكىتلەيدۇ.","wushidao sadiqliq we sherepni tekitleydu."]],"步足":[["昆虫的步足帮助它们行走。","ھاشاراتلارنىڭ يۈرۈش پۇتلىرى ئۇلارغا مېڭىشقا ياردەم بېرىدۇ.","hasharatlarning yürüsh putliri ulargha méngishqa yardem béridu."]],"武功镇":[["武功镇以当地的武术文化闻名。","ۋۇگۇڭ بازىرى يەرلىك ۋۇشۇ مەدەنىيىتى بىلەن داڭلىق.","wugung baziri yerlik wushu medeniyiti bilen dangliq."]],"杀戮":[["战争带来了巨大的杀戮和破坏。","ئۇرۇش زور قىرغىنچىلىق ۋە ۋەيرانچىلىق ئېلىپ كەلدى.","urush zor qirghinchiliq we weyranchiliq élip keldi."]],"比烂":[["他们比烂谁更差。","ئۇلار كىمنىڭ تېخىمۇ ناچارلىقىنى سېلىشتۇرىدۇ.","ular kimning téximu nacharliqini sélishturidu."]],"残香":[["残香在空气中弥漫。","قالدۇق خۇشپۇراق ھاۋادا تارقالماقتا.","qalduq xushpuraq hawada tarqalmaqta."]],"毛利":[["毛利是毛利人的传统服饰。","ماۋرى كىيىمى ماۋرى خەلقىنىڭ ئەنئەنىۋى كىيىمىدۇر.","mawri kiyimi mawri xelqining en'eniwi kiyimidur."]],"氧化铝":[["氧化铝常用于制造耐高温的陶瓷材料。","ئوكسىدلانغان ئاليۇمىن يۇقىرى تېمپېراتۇرىغا چىداملىق ساپال ماتېرىياللارنى ئىشلەپچىقىرىشتا كۆپ ئىشلىتىلىدۇ.","oksidlanghan alyumin yuqiri témpératurigha chidamliq sapal matériyallarni ishlepchiqirishta köp ishlitilidu."]],"水上运动":[["水上运动包括划船、冲浪等多种项目。","سۇ ئۈستى تەنتەربىيەسىگە ئېشەك كېمە، دولقۇن تېيىلىش قاتارلىق كۆپ خىل تۈرلەر كىرىدۇ.","su üsti tenterbiyesige éshek kéme, dolqun téyilish qatarliq köp xil türler kiridu."]],"水牢":[["古代的水牢极其残酷可怕。","قەدىمكى سۇ زىندانى ئىنتايىن رەھىمسىز ۋە قورقۇنچلۇق ئىدى.","qedimki su zindani intayin rehimsiz we qorqunchluq idi."]],"永和市":[["永和市交通便利。","يۇڭخې شەھىرىنىڭ قاتناشى قولايلىق.","yungxé shehirining qatnashi qolayliq."]],"水产品":[["这些水产品营养丰富。","بۇ سۇ مەھسۇلاتلىرى ئوزۇقلۇق ماددىلارغا باي.","bu su mehsulatliri ozuqluq maddilargha bay."]],"水产养殖":[["水产养殖技术不断进步。","سۇ مەھسۇلاتلىرى بېقىش تېخنىكىسى ئۈزلۈكسىز ئىلگىرىلەۋاتىدۇ.","su mehsulatliri béqish téxnikisi üzlüksiz ilgirilewatidu."]],"民盟":[["民盟是中国重要的民主党派。","خەلق ئىتتىپاقى جۇڭگونىڭ مۇھىم دېموكراتىك پارتىيىسىدۇر.","xelq ittipaqi junggoning muhim démokratik partiyisidur."]],"民变峰起":[["各地民变峰起，局势紧张。","ھەر جايدا خەلق قوزغىلىڭى ئۆرلەپ، ۋەزىيەت جىددىيلەشتى.","her jayda xelq qozghilingi örlep, weziyet jiddiyleshti."]],"汽车技工":[["这位汽车技工擅长修理发动机。","بۇ ئاپتوموبىل تېخنىكىسى ماتورنى رېمونت قىلىشقا ماھىر.","bu aptomobil téxnikisi matorni rémont qilishqa mahir."]],"没药":[["家里没药了，他只能忍着痛。","ئۆيدە دورا قالمىدى، ئۇ چىدىغاندىن باشقا ئامالى يوق.","öyde dora qalmidi, u chidighandin bashqa amali yoq."]],"汗如雨下":[["他紧张得汗如雨下。","ئۇ ھەددىدىن زىيادە تەرلەپ، تەرى يامغۇردەك تۆكۈلدى.","u heddidin ziyade terlep, teri yamghurdek töküldi."]],"沙僧":[["沙僧是《西游记》中的角色。","شا سېڭ «غەربكە سەپەر» دىكى رول.","sha séng «gherbke seper» diki rol."]],"沙坑杆":[["他拿起沙坑杆开始挖洞。","ئۇ قۇم ئوچۇقى ئاسقۇچىنى كۆتۈرۈپ تۆشۈك قازىشقا باشلىدى.","u qum ochuqi asquchini kötürüp töshük qazishqa bashlidi."]],"沙坡头区":[["沙坡头区以沙漠景观闻名。","شاپوتوۋ رايونى چۆل مەنزىرىسى بىلەن داڭلىق.","shapotow rayoni chöl menzirisi bilen dangliq."]],"沙坪坝区":[["沙坪坝区有许多历史遗迹。","شاپىڭبا رايونىدا نۇرغۇن تارىخىي ئابىدە بار.","shapingba rayonida nurghun tarixiy abide bar."]],"没奈何":[["他只能没奈何地接受。","ئۇ باشقا ئامالسىز قوبۇل قىلدى.","u bashqa amalsiz qobul qildi."]],"法蒂玛":[["法蒂玛是伊斯兰教的重要人物。","فاتىما ئىسلام دىنىنىڭ مۇھىم شەخسى.","fatima islam dinining muhim shexsi."]],"油症":[["这种油症需要及时治疗。","بۇ خىل ماي كېسىلىنى ۋاقتىدا داۋالاش كېرەك.","bu xil may késilini waqtida dawalash kérek."]],"波多黎各":[["波多黎各是加勒比海的一个岛屿。","پۇئېرتو رىكو كارىب دېڭىزىدىكى بىر ئارالدۇر.","puérto riko karib déngizidiki bir araldur."]],"波德里查":[["波德里查是斯洛文尼亚的一个村庄。","بودرىچا سلوۋېنىيەدىكى بىر كەنتتۇر.","bodricha slowéniyediki bir kenttur."]],"法衣":[["僧侣穿着庄严的法衣。","روھانىيلار تەنتەنىلىك دىنىي كىيىم كىيىدۇ.","rohaniylar tentenilik diniy kiyim kiyidu."]],"泰州":[["泰州是江苏省的一座城市。","تەيجۇ جياڭسۇ ئۆلكىسىدىكى بىر شەھەر.","teyju jyangsu ölkisidiki bir sheher."]],"洋香菜":[["洋香菜和香菜味道相似。","فرانسۇز رەيحانى بىلەن رەيحاننىڭ تەمى ئوخشاش.","fransuz reyحani bilen reyحanning temi oxshash."]],"洗劫一空":[["仓库里的货物被洗劫一空。","ئامباردىكى ماللار تالان-تاراج قىلىنىپ تۈگىدى.","ambardiki mallar talan-taraj qilinip tügidi."]],"泄欲":[["他沉迷于网络来泄欲。","ئۇ تورغا بېرىلىپ نەپسى خاھىشىنى چىقىرىدۇ.","u torgha bérilip nepsi xahishini chiqiridu."]],"洛神花":[["洛神花是一种美丽的观赏植物。","روزېللە گۈلى بىر گۈزەل مەنزىرە ئۆسۈملۈكىدۇر.","rozélle güli bir güzel menzire ösümlükidur."]],"治愈系":[["治愈系作品能缓解压力。","ساقايتىش تۈسىدىكى ئەسەرلەر بېسىمنى يېنىكلىتەلەيدۇ.","saqaytish tüsidiki eserler bésimni yénikliteleydu."]],"流浪狗":[["流浪狗常常在街头觅食。","ئاقار ئىتلار كوچىلاردا دائىم يېمەكلىك ئىزدەيدۇ.","aqar itlar kochilarda daim yémeklik izdeydu."]],"浣纱":[["浣纱是古代女子的劳作。","يىپ يۇيۇش قەدىمكى زامان ئاياللىرىنىڭ ئەمگىكى ئىدى.","yip yuyush qedimki zaman ayallirining emgiki idi."]],"浦北县":[["浦北县以水果闻名。","پۇبېي ناھىيىسى مېۋە-چېۋىسى بىلەن داڭلىق.","pubéy nahiyisi méwe-chéwisi bilen dangliq."]],"海内":[["海内皆兄弟，情谊深厚。","دېڭىز ئىچىدىكىلەرنىڭ ھەممىسى قېرىنداش، دوستلۇق چوڭقۇر.","déngiz ichidikilerning hemmisi qérindash, dostluq chongqur."]],"海涅":[["海涅是德国著名的诗人和思想家。","خەينې گېرمانىيەنىڭ ئاتاقلىق شائىرى ۋە مۇتەپەككۇرى.","xeyné gérmaniyening ataqliq shairi we mutepekkuri."]],"浮潜":[["浮潜时需要注意水下安全。","سۇ ئاستى بىخەتەرلىكىگە دىققەت قىلىش كېرەك سۇ ئاستىدا لەيلىگەندە.","su asti bixeterlikige diqqet qilish kérek su astida leyligende."]],"涉众":[["涉众问题需要谨慎处理。","كۆپچىلىككە چېتىلىدىغان مەسىلىلەرنى ئېھتىيات بىلەن بىر تەرەپ قىلىش كېرەك.","köpchilikke chétilidighan mesililerni éhtiyat bilen bir terep qilish kérek."]],"消防员":[["消防员迅速赶到现场进行救援。","ئوت ئۆچۈرۈش خادىملىرى دەرھال ۋەقە جايىغا يېتىپ بېرىپ قۇتقۇزۇش ئېلىپ باردى.","ot öchürüsh xadimliri derhal weqe jayigha yétip bérip qutquzush élip bardi."]],"深层政府":[["深层政府影响深远。","چوڭقۇر قاتلام ھۆكۈمىتىنىڭ تەسىرى چوڭقۇر.","chongqur qatlam hökümitining tesiri chongqur."]],"深广":[["深广两地合作密切。","شېنزېن بىلەن گۇاڭجۇ ئوتتۇرىسىدىكى ھەمكارلىق زىچ.","shénzén bilen guangju otturisidiki hemkarliq zich."]],"深棕色":[["深棕色是秋冬季节的流行色。","چوڭقۇر قوڭۇر رەڭ كۈز-قىش پەسلىنىڭ مودا رەڭگى.","chongqur qongur reng küz-qish peslining moda renggi."]],"清仓":[["仓库需要尽快清仓。","ئامبارنى تېزلىكتە قۇرۇقلۇتۇش كېرەك.","ambarni tézlikte quruqlutush kérek."]],"清嗓":[["他清了清嗓子开始演讲。","ئۇ ئاۋازىنى ئېنىقلاپ سۆز قىلىشقا باشلىدى.","u awazini éniqlap söz qilishqa bashlidi."]],"淤青":[["他手臂上的淤青逐渐消退了。","ئۇنىڭ بىلىكىدىكى كۆكەرگەن داغ تەدرىجىي يوقاپ كەتتى.","uning bilikidiki kökergen dagh tedrijiy yoqap ketti."]],"港务局":[["港务局负责管理港口事务。","پورت ئىدارىسى پورت ئىشلىرىنى باشقۇرۇشقا مەسئۇل.","port idarisi port ishlirini bashqurushqa mes'ul."]],"海隅":[["海隅之地风景优美。","دېڭىز بۇرجىكىدىكى جاي مەنزىرىسى گۈزەلدۇر.","déngiz burjikidiki jay menzirisi güzeldur."]],"浸润":[["雨水浸润了干涸的土地。","يېغىن سۇسىز زېمىننى ھۆل قىلدى.","yéghin susiz zéminni höl qildi."]],"湘妃竹":[["湘妃竹是一种珍贵的竹子。","شياڭفېي بامبۇكى قىممەتلىك بىر خىل بامبۇك.","shyangféy bambuki qimmetlik bir xil bambuk."]],"准头":[["他的射击准头很高。","ئۇنىڭ ئوق چىقىرىش نىشانى ئىنتايىن يۇقىرى.","uning oq chiqirish nishani intayin yuqiri."]],"港澳地区":[["港澳地区是重要的国际金融中心。","شياڭگاڭ بىلەن ئاۋمېن رايونى مۇھىم خەلقئارا مالىيە مەركىزىدۇر.","shyanggang bilen awmén rayoni muhim xelq'ara maliye merkizidur."]],"渗入":[["雨水逐渐渗入地下层。","يامغۇر سۈيى تەدرىجىي يەر ئاستى قاتلىمىغا سىڭىپ كىردى.","yamghur süyi tedrijiy yer asti qatlimigha singip kirdi."]],"满贯":[["他连续三年获得冠军，实现了满贯的壮举。","ئۇ ئارقا-ئارقىدىن ئۈچ يىل چېمپىيون بولۇپ، تولۇق غەلىبە قازاندى.","u arqa-arqidin üch yil chémpiyon bolup, toluq ghelibe qazandi."]],"澳币":[["他用澳币买了一杯咖啡。","ئۇ ئاۋسترىيە پۇلى بىلەن بىر ئىستاكان قەھۋە سېتىۋالدى.","u awstriye puli bilen bir istakan qehwe sétiwaldi."]],"润滑油":[["润滑油用于发动机保养。","ماي ماشىنا ماتورىنى ئاسراشقا ئىشلىتىلىدۇ.","may mashina matorini asrashqa ishlitilidu."]],"润笔":[["书法家润笔后开始创作。","خەتتاتلىق ئۇستىسى قەلەمنى مايلىغاندىن كېيىن ئىجادىيەتكە باشلىدى.","xettatliq ustisi qelemni maylighandin kéyin ijadiyetke bashlidi."]],"滨湖":[["滨湖公园是市民休闲的好去处。","بىنخۇ باغچىسى شەھەر ئاھالىسىنىڭ ئارام ئېلىشى ئۈچۈن ياخشى جاي.","binxu baghchisi sheher ahalisining aram élishi üchün yaxshi jay."]],"滦南县":[["滦南县以优质的农产品著称。","لۈەننەن ناھىيىسى سۈپەتلىك يېزا ئىگىلىك مەھسۇلاتلىرى بىلەن تونۇلغان.","lüennen nahiyisi süpetlik yéza igilik mehsulatliri bilen tonulghan."]],"乌兰浩特市":[["乌兰浩特市位于内蒙古东南部。","ئۇلانخوت شەھىرى ئىچكى موڭغۇلنىڭ جەنۇبىي شەرقىدە جايلاشقان.","ulanxot shehiri ichki mongghulning jenubiy sherqide jaylashqan."]],"为五斗米折腰":[["他不愿为五斗米折腰。","ئۇ بەش دان سېرىق پۇل ئۈچۈن بېلىنى ئېگىشكە خالىمايدۇ.","u besh dan sériq pul üchün bélini égishke xalimaydu."]],"无用之树":[["这棵无用之树被砍了。","بۇ پايدىسىز دەرەخ كېسىلدى.","bu paydisiz derex késildi."]],"无明":[["无明是佛教中烦恼的根源之一。","ئىناۋەتسىزلىك بۇددا دىنىدا غەم-قايغۇنىڭ مەنبەلىرىدىن بىرى.","inawetsizlik budda dinida ghem-qayghuning menbeliridin biri."]],"无后":[["他无后，令人遗憾。","ئۇنىڭ ئەۋلادى يوق، بۇ ئەپسۇسلىنارلىق.","uning ewladi yoq, bu epsuslinarliq."]],"无思无虑":[["他从小无思无虑，无忧无虑地长大。","ئۇ كىچىكىدىن ئەندىشىسىز، غەمسىز ئۆسۈپ يېتىلدى.","u kichikidin endishisiz, ghemsiz ösüp yétildi."]],"煽动颠覆国家政权":[["煽动颠覆国家政权是犯罪行为。","دۆلەت ھاكىمىيىتىنى ئاغدۇرۇشقا قۇترىتىش جىنايى قىلمىش.","dölet hakimiyitini aghdurushqa qutritish jinayi qilmish."]],"熊狸":[["熊狸是一种生活在森林中的动物。","ئېيىق مۈشۈكى ئورمانلىقتا ياشايدىغان بىر خىل ھايۋان.","éyiq müshüki ormanliqta yashaydighan bir xil haywan."]],"焙烧":[["焙烧用于陶瓷或矿石的烧制。","بېيشاۋ ساپال ياكى مەدەنلەرنى كۆيدۈرۈشتە ئىشلىتىلىدۇ.","béyshaw sapal yaki medenlerni köydürüshte ishlitilidu."]],"牛腩":[["牛腩炖得软烂入味。","كالا قورساق گۆشى يۇمشاق پىشىپ تەمگە سىڭگەن.","kala qorsaq göshi yumshaq piship temge singgen."]],"墙头草":[["墙头草随风倒，毫无主见。","تام بېشىدىكى ئوت-چۆپ شامالغا ئەگىشىپ يىقىلىدۇ، ھېچقانداق ئۆز كۆز قارىشى يوق.","tam béshidiki ot-chöp shamalgha egiship yiqilidu, héchqandaq öz köz qarishi yoq."]],"争得":[["经过努力，他终于争得了参赛资格。","تىرىشچانلىقى ئارقىلىق، ئۇ ئاخىرىدا مۇسابىقىگە قاتنىشىش سالاھىيىتىگە ئېرىشتى.","tirishchanliqi arqiliq, u axirida musabiqige qatnishish salahiyitige érishti."]],"玉林":[["玉林是广西壮族自治区的城市。","يۈلىن گۇاڭشى جۇاڭزۇ ئاپتونوم رايونىدىكى بىر شەھەر.","yülin guangshi juangzu aptonom rayonidiki bir sheher."]],"猎隼":[["猎隼擅长高空捕猎。","ئوۋ لاچىنى ئېگىز ئاسماندا ئوۋ ئوۋلاشقا ماھىر.","ow lachini égiz asmanda ow owlashqa mahir."]],"狰狞":[["怪物露出狰狞的面容，令人恐惧。","ئالۋاستى قەبىھ چىرايىنى كۆرسىتىپ، كىشىنى قورقۇتتى.","alwasti qebih chirayini körsitip, kishini qorqutti."]],"现学现用":[["他现学现用，很快掌握了技巧。","ئۇ ئۆگەنگەن ھامان ئىشلىتىپ، تېزلا ماھارەتنى ئىگىلىدى.","u ögengen haman ishlitip, tézla maharetni igilidi."]],"玳瑁":[["玳瑁是一种珍贵的海龟。","تاشپاقا بىر خىل قىممەتلىك دېڭىز تاشپاقىسىدۇر.","tashpaqa bir xil qimmetlik déngiz tashpaqisidur."]],"玻璃化":[["材料经过加热后会玻璃化。","ماتېرىيال قىزىتىلغاندىن كېيىن ئەينەكلىنىدۇ.","matériyal qizitilghandin kéyin eyneklinidu."]],"珀西·比希·雪莱":[["珀西·比希·雪莱是英国浪漫派诗人。","پېرسى بىشى شېللى ئەنگلىيە رومانتىك شائىرىدۇر.","pérsi bishi shélli engliye romantik shairidur."]],"生活作风":[["良好的生活作风值得学习。","Yaxshi turmush ئەندىزىسى ئۆگىنىشكە ئەرزىيدۇ.","Yaxshi turmush endizisi öginishke erziydu."]],"生物战":[["生物战使用病原体攻击敌方部队。","Biologik urush patogenlar ئارقىلىق دۈشمەن قىسىملىرىغا ھۇجۇم قىلىدۇ.","Biologik urush patogenlar arqiliq düshmen qisimlirigha hujum qilidu."]],"甲铠":[["古代士兵身穿厚重的甲铠。","قەدىمكى دەۋر ئەسكەرلىرى ئېغىر جابدۇق كىيىپ يۈرەتتى.","qedimki dewr eskerliri éghir jabduq kiyip yüretti."]],"留级":[["他因功课落后而留级了。","ئۇ دەرسلەردىن ئارقىدا قالغانلىقى ئۈچۈن سىنىپتا قالدى.","u derslerdin arqida qalghanliqi üchün sinipta qaldi."]],"产卵":[["母鸟开始产卵了。","ئانا قۇش تۇخۇم تۇغۇشقا باشلىدى.","ana qush tuxum tughushqa bashlidi."]],"略阳":[["略阳的山水风光令人流连忘返。","لۈەيياڭنىڭ تاغ-سۇ مەنزىرىسى كىشىنى ئايرىلغۇسىز قىلىدۇ.","lüeyyangning tagh-su menzirisi kishini ayrilghusiz qilidu."]],"画眉":[["她画眉的手法非常自然生动。","ئۇنىڭ قاش سىزىش ئۇسۇلى ناھايىتى تەبىئىي ۋە جانلىق.","uning qash sizish usuli nahayiti tebiiy we janliq."]],"界尺":[["界尺是古代测量土地的工具。","چېگرا ئۆلچىگۈچ قەدىمكى زاماندا يەر ئۆلچەيدىغان ئەسۋاب ئىدى.","chégra ölchigüch qedimki zamanda yer ölcheydighan eswab idi."]],"当断则断":[["当断则断，犹豫不决有害无益。","كېسىش كېرەك بولغاندا كېسىش كېرەك، ئىككىلىنىش زىيانسىز پايدىسىز.","késish kérek bolghanda késish kérek, ikkilinish ziyansiz paydisiz."]],"发酒疯":[["他喝醉后开始发酒疯。","ئۇ مەست بولغاندىن كېيىن ئىچىملىك ئىچىپ ساراڭلىق قىلىشقا باشلىدى.","u mest bolghandin kéyin ichimlik ichip sarangliq qilishqa bashlidi."]],"百无聊赖":[["他在房间里百无聊赖，不知道做什么。","ئۇ ئۆيىدە زېرىكىپ، نېمە قىلىشنى بىلمەي قالدى.","u öyide zérikip, néme qilishni bilmey qaldi."]],"研求":[["他致力于研求更高效的能源技术。","ئۇ تېخىمۇ يۇقىرى ئۈنۈملۈك ئېنېرگىيە تېخنىكىسىنى تەتقىق قىلىشقا بېغىشلىدى.","u téximu yuqiri ünümlük énérgiye téxnikisini tetqiq qilishqa béghishlidi."]],"竹篱笆":[["竹篱笆围成的小院，充满田园气息。","بامبۇك قورشاۋ بىلەن ئورالغان كىچىك ھويلى ئېتىز-ئېرىق ھىدىگە تولغان.","bambuk qorshaw bilen oralghan kichik hoyli étiz-ériq hidige tolghan."]],"笑星":[["他是家喻户晓的喜剧笑星。","ئۇ ھەممە ئائىلىلەرگە تونۇشلۇق كومېدىيە كۈلكىلىك يۇلتۇزى.","u hemme aililerge tonushluq komédiye külkilik yultuzi."]],"纱线":[["纱线用于编织衣物。","يىپ كىيىم-كېچەك توقۇشقا ئىشلىتىلىدۇ.","yip kiyim-kéchek toqushqa ishlitilidu."]],"细胞培养器":[["细胞培养器为细胞提供适宜的生长环境。","ھۈجەيرە ئۆستۈرۈش ئۈسكۈنىسى ھۈجەيرىلەرگە مۇۋاپىق ئۆسۈش مۇھىتى تەمىنلەيدۇ.","hüjeyre östürüsh üskünisi hüjeyrilerge muwapiq ösüsh muhiti teminleydu."]],"细说":[["请详细说一说你的想法。","ئويلىرىڭىزنى تەپسىلىي سۆزلەپ بېرىڭ.","oyliringizni tepsiliy sözlep béring."]],"纸带":[["纸带可以用来装饰礼物。","قەغەز لېنتا سوۋغاتنى بېزەشكە ئىشلىتىلىدۇ.","qeghez lénta sowghatni bézeshke ishlitilidu."]],"纸书":[["纸书比电子书更有质感。","قەغەز كىتاب ئېلېكترونلۇق كىتابتىن تېخىمۇ ھېسسىياتلىق.","qeghez kitab éléktronluq kitabtin téximu héssiyatliq."]],"紫翅椋鸟":[["紫翅椋鸟在枝头欢快地歌唱。","بىنەپشە قاناتلىق چىلەن قۇش شاخ ئۈستىدە خۇشال سايرايدۇ.","binepshe qanatliq chilen qush shax üstide xushal sayraydu."]],"结缡":[["结缡象征婚姻的缔结。","نىكاھ تۇيى بەختلىك تۇرمۇشنىڭ باغلىنىشىنى سىمۋوللاشتۇرىدۇ.","nikah tuyi bextlik turmushning baghlinishini simwollashturidu."]]};
